insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('db000000-0000-0000-0000-000000000001', 'mrcp2', '88deb7cd-4cc0-43cb-8036-896c04d2f1c0',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('db000000-0000-0000-0000-000000000001', 'A', $x$Hold a best interests meeting involving the multidisciplinary team, the patient's family, and anyone else interested in her welfare, to reach a decision based on her known wishes, values and beliefs$x$, true, 'Correct. Under the Mental Capacity Act 2005, a best interests decision for a patient lacking capacity requires proper consultation with those close to the patient and consideration of her previously expressed wishes, values and beliefs, led by the treating clinician.', 1),
('db000000-0000-0000-0000-000000000001', 'B', 'Ask the child who wants continued active treatment to act as the decision-maker since they are advocating for more intervention', false, 'Ruled out because neither child has legal decision-making authority, and decisions should not be allocated to whichever relative is more assertive about a particular course of action.', 2),
('db000000-0000-0000-0000-000000000001', 'C', 'Refer immediately to the Court of Protection for a ruling before any decision can be made', false, 'Ruled out because court referral is reserved for situations where a proper best interests process cannot resolve genuine disagreement, not as an automatic first step.', 3),
('db000000-0000-0000-0000-000000000001', 'D', 'Since there is no LPA, treatment decisions default to whichever option preserves life, such as continuing chemotherapy regardless of her encephalopathy', false, $x$Ruled out because there is no such default rule; decisions must be based on an individualised best interests assessment, not a blanket 'life at all costs' principle.$x$, 4),
('db000000-0000-0000-0000-000000000001', 'E', 'Because she lacks capacity, decisions should be made solely by the most senior treating clinician without involving the family', false, 'Ruled out because although the clinician holds ultimate responsibility, the family and anyone else interested in her welfare must be consulted as part of the best interests process.', 5),
('db000000-0000-0000-0000-000000000002', 'A', $x$The patient's wish for CPR to be attempted must be honoured regardless of clinical judgement, as he retains capacity$x$, false, 'Ruled out because capacity gives a patient the right to refuse treatment, not to demand a treatment (including CPR) that the team judges to be clinically futile.', 1),
('db000000-0000-0000-0000-000000000002', 'B', 'The consultant can complete a DNACPR order if CPR is judged very unlikely to succeed, but must explain the clinical reasoning to the patient and offer him the opportunity to seek a second opinion', true, 'Correct. CPR decisions differ from other treatment decisions: a capacitous patient cannot demand a treatment judged clinically futile, but good practice requires open discussion of the rationale and an offer of a second opinion.', 2),
('db000000-0000-0000-0000-000000000002', 'C', 'CPR should be attempted purely because the patient asked, without further discussion', false, 'Ruled out because this omits the necessary sensitive discussion of clinical reasoning and the offer of a second opinion that should accompany a DNACPR decision.', 3),
('db000000-0000-0000-0000-000000000002', 'D', 'The DNACPR decision should be deferred to family after the patient loses capacity rather than made now', false, 'Ruled out because decisions like this should be made and documented in real time while the patient can be involved, not deferred unnecessarily.', 4),
('db000000-0000-0000-0000-000000000002', 'E', 'Because he has capacity, a DNACPR order cannot legally be documented at all until he loses capacity', false, 'Ruled out because a DNACPR order can be completed whenever clinically appropriate; capacity does not prevent a clinician-led futility decision, though sensitive communication is required.', 5),
('db000000-0000-0000-0000-000000000003', 'A', 'The ADRT is invalid because she cannot currently confirm it now that she lacks capacity', false, $x$Ruled out because an ADRT's validity is assessed at the time it was made; a later loss of capacity does not itself invalidate a properly completed ADRT.$x$, 1),
('db000000-0000-0000-0000-000000000003', 'B', 'Because the respiratory failure is precipitated by a reversible chest infection rather than pure MND progression, the ADRT does not apply and ventilation should be started', false, 'Ruled out because the infection is precipitating failure in the context of underlying MND weakness, exactly the anticipated scenario she described.', 2),
('db000000-0000-0000-0000-000000000003', 'C', 'Family wishes should override the ADRT since they know her best', false, 'Ruled out because a valid and applicable ADRT is legally binding and takes precedence over family wishes.', 3),
('db000000-0000-0000-0000-000000000003', 'D', 'The ADRT should be treated as valid and applicable, since the current situation matches the specific circumstances she anticipated, and ventilation should not be initiated', true, 'Correct. A valid and applicable ADRT is legally binding; respiratory failure due to MND-related weakness, even precipitated by an infection, falls within the scenario she specifically anticipated.', 4),
('db000000-0000-0000-0000-000000000003', 'E', $x$Ventilation should be started temporarily pending Court of Protection review of the ADRT's validity$x$, false, 'Ruled out because this is an unnecessary court referral when the ADRT is clearly valid and applicable, and would violate her documented wishes in the interim.', 5),
('db000000-0000-0000-0000-000000000004', 'A', 'Since the son holds LPA for health and welfare, his decision for full escalation must be followed regardless of clinical judgement', false, 'Ruled out because an LPA does not grant power to demand treatment against clinical judgement or best interests.', 1),
('db000000-0000-0000-0000-000000000004', 'B', 'The LPA is automatically overridden whenever the treating team disagrees with the attorney', false, 'Ruled out because disagreement should trigger a structured resolution process (second opinion, mediation, Court of Protection if needed), not automatic override.', 2),
('db000000-0000-0000-0000-000000000004', 'C', 'The team should proceed directly to Court of Protection without attempting further discussion or a second opinion', false, 'Ruled out because court escalation is a last resort after other resolution steps have been tried.', 3),
('db000000-0000-0000-0000-000000000004', 'D', 'Because the patient lacks capacity and there is a valid LPA, clinicians have no further obligations regarding best interests', false, 'Ruled out because best interests remains the governing principle even when there is a registered LPA holder.', 4),
('db000000-0000-0000-0000-000000000004', 'E', $x$Explain to the son that an LPA holder's decisions must still be in the patient's best interests, and if the team believes escalation is not in his best interests, a second opinion or mediation should be sought rather than proceeding with ICU admission$x$, true, $x$Correct. LPA authority is not absolute; the attorney must act in the patient's best interests, and clinicians are not obliged to provide treatment judged clinically inappropriate; disagreement should be escalated via second opinion or mediation.$x$, 5),
('db000000-0000-0000-0000-000000000005', 'A', 'Because her capacity fluctuates, she should be deemed to permanently lack capacity for all future decisions', false, 'Ruled out because capacity assessment is decision-specific and time-specific, not a permanent global label.', 1),
('db000000-0000-0000-0000-000000000005', 'B', 'The decision should be deferred to next of kin automatically since her capacity is inconsistent', false, 'Ruled out because if she can be supported to have capacity at some points in the day, her own decision should be used first.', 2),
('db000000-0000-0000-0000-000000000005', 'C', 'Capacity should be assessed at the time the specific decision needs to be made, ideally when she is at her most lucid, rather than assuming incapacity based on her morning presentation', true, 'Correct. Capacity is decision-specific and time-specific; every effort should be made to time the assessment when the patient is best able to demonstrate capacity.', 3),
('db000000-0000-0000-0000-000000000005', 'D', 'Since she lacks capacity in the morning, any decision made then should stand as her definitive wishes even if she later disagrees when lucid', false, 'Ruled out because decisions made while she lacks capacity for that decision should not be treated as her considered, informed wishes.', 4),
('db000000-0000-0000-0000-000000000005', 'E', 'A formal psychiatric assessment must be obtained before any capacity assessment can be performed on a patient with a brain tumour', false, 'Ruled out because capacity assessment is a clinical assessment by the treating team using the two-stage test, not one that necessarily requires psychiatric referral.', 5),
('db000000-0000-0000-0000-000000000006', 'A', 'Continue dialysis indefinitely because the wife has requested it, regardless of the clinical assessment', false, 'Ruled out because clinicians are not obliged to provide treatment assessed as futile solely on family request.', 1),
('db000000-0000-0000-0000-000000000006', 'B', 'Stop dialysis immediately without further discussion since the clinical team have already reached a decision', false, 'Ruled out because communication and, where needed, a second opinion should precede withdrawal, particularly given family disagreement.', 2),
('db000000-0000-0000-0000-000000000006', 'C', 'Transfer the decision entirely to the wife as next of kin, since she knows him best', false, 'Ruled out because next of kin do not have legal decision-making authority unless holding LPA, though their views should be actively sought.', 3),
('db000000-0000-0000-0000-000000000006', 'D', 'Arrange a family meeting to explain the clinical reasoning and prognosis honestly, seek a second opinion if significant disagreement remains, and involve the palliative care team to support decision-making and symptom management', true, 'Correct. Withdrawal decisions should follow honest communication and, where disagreement persists, a second opinion, with palliative care support alongside organ-support specialists.', 4),
('db000000-0000-0000-0000-000000000006', 'E', 'Refer directly to the Court of Protection before any further clinical discussion', false, 'Ruled out because court referral is a last resort when other measures fail to resolve disagreement.', 5),
('db000000-0000-0000-0000-000000000007', 'A', 'Proceed with surgical decompression purely because the family requested it, overriding the MDT clinical assessment', false, 'Ruled out because treatment decisions should be guided by clinical assessment of likely benefit, not family demand alone.', 1),
('db000000-0000-0000-0000-000000000007', 'B', 'Avoid discussing prognosis with the family to prevent distress, and make the decision unilaterally without their input', false, 'Ruled out because honest, sensitive communication is essential; excluding the family from difficult conversations is poor practice.', 2),
('db000000-0000-0000-0000-000000000007', 'C', 'Hold a compassionate, honest conversation with the family explaining the prognosis and the limited likely benefit of aggressive intervention, exploring their concerns, and involving palliative care to support both symptom control and the family through the decision', true, 'Correct. Decisions should be guided by an honest assessment of likely benefit and prognosis, communicated compassionately, with palliative care support for the family.', 3),
('db000000-0000-0000-0000-000000000007', 'D', 'Insist the family accept the clinical decision immediately without further discussion since the medical team has already reached consensus', false, 'Ruled out because further discussion and time for the family to process the decision should be facilitated.', 4),
('db000000-0000-0000-0000-000000000007', 'E', 'Refer the case immediately to the Court of Protection because the family disagrees with the clinical team', false, 'Ruled out because disagreement alone does not warrant court referral until communication and other resolution steps have been tried.', 5),
('db000000-0000-0000-0000-000000000008', 'A', 'There is no meaningful legal or ethical distinction between palliative sedation and euthanasia, as both foreseeably hasten death', false, 'Ruled out because intention behind the act meaningfully distinguishes the two, both ethically and legally in England and Wales.', 1),
('db000000-0000-0000-0000-000000000008', 'B', 'Palliative sedation is illegal in the UK and cannot be offered even for refractory symptoms', false, 'Ruled out because proportionate sedation is an accepted and lawful part of palliative care.', 2),
('db000000-0000-0000-0000-000000000008', 'C', 'Because the patient has explicitly requested that sedation hasten his death, providing sedation constitutes euthanasia and is unlawful', false, 'Ruled out because this mischaracterises intent; the aim is symptom relief, not ending life, even though the patient understands it may shorten life.', 3),
('db000000-0000-0000-0000-000000000008', 'D', 'Palliative sedation should only ever be given at a fixed, non-titrated dose regardless of ongoing symptoms', false, 'Ruled out because sedation should be titrated to achieve symptom relief using the lowest effective dose, not a fixed regimen.', 4),
('db000000-0000-0000-0000-000000000008', 'E', 'Proportionate palliative sedation aims to relieve otherwise intractable suffering using the lowest effective dose of sedative titrated to symptom control, with death (if it occurs) as a foreseen but unintended consequence, whereas euthanasia involves the direct intentional ending of life', true, 'Correct. The doctrine of double effect distinguishes sedation aimed at symptom relief (with death as an unintended, foreseen possibility) from euthanasia, which directly intends death.', 5),
('db000000-0000-0000-0000-000000000009', 'A', 'Proceed with the best interests decision to focus on comfort, ensuring it is well documented following an MDT and family discussion, without needing to refer to the Court of Protection since there is no dispute', true, $x$Correct. Following An NHS Trust v Y (2018), court authorisation is not required for CANH withdrawal when there is agreement among the clinical team and family that this is in the patient's best interests.$x$, 1),
('db000000-0000-0000-0000-000000000009', 'B', 'A Court of Protection application is mandatory in every case involving withdrawal of clinically assisted nutrition and hydration, regardless of family agreement', false, 'Ruled out because per current guidance, court involvement is only required for disputed or highly finely balanced cases.', 2),
('db000000-0000-0000-0000-000000000009', 'C', 'Because she lacks capacity and has no LPA, only the local authority can authorise withdrawal of nutrition and hydration', false, 'Ruled out because decisions are made via the standard best interests process led by the treating clinician in consultation with those close to the patient.', 3),
('db000000-0000-0000-0000-000000000009', 'D', 'An IMCA must be appointed and their agreement obtained before any decision can proceed, even though engaged family members are already involved and in agreement', false, 'Ruled out because IMCA involvement is required when there is no family or friends appropriate to consult, not when engaged, agreeing family are already present.', 4),
('db000000-0000-0000-0000-000000000009', 'E', $x$The decision should be delayed indefinitely until the patient's condition further deteriorates to remove any ambiguity$x$, false, 'Ruled out because unnecessary delay is not appropriate once a proper best interests decision has been reached.', 5),
('db000000-0000-0000-0000-000000000010', 'A', 'Refuse to withdraw NIV because doing so would be considered a form of assisted death', false, $x$Ruled out because withdrawing a life-sustaining treatment at the request of a capacitous patient is legally and ethically distinct from assisted dying; it is respecting the patient's right to refuse treatment.$x$, 1),
('db000000-0000-0000-0000-000000000010', 'B', 'Respect his autonomous, capacitous decision to withdraw NIV, and proactively plan a terminal wean with anticipatory prescribing of opioids and benzodiazepines to manage breathlessness and distress as ventilatory support is reduced', true, 'Correct. A capacitous patient has the right to withdraw consent to a life-sustaining treatment, and a planned terminal wean with anticipatory symptom control is standard good practice.', 2),
('db000000-0000-0000-0000-000000000010', 'C', 'Withdraw NIV abruptly without anticipatory symptom management, since the outcome is inevitable', false, 'Ruled out because a planned terminal wean with pre-emptive symptom control is standard good practice to minimise distress.', 3),
('db000000-0000-0000-0000-000000000010', 'D', 'Require psychiatric clearance to confirm he is not depressed before honouring his wish to withdraw NIV', false, 'Ruled out because while screening for low mood is good holistic practice, a capacitous, considered decision to stop a burdensome treatment does not require psychiatric sign-off as a precondition.', 4),
('db000000-0000-0000-0000-000000000010', 'E', 'Only permit withdrawal of NIV if the family agree, given the significant consequence', false, $x$Ruled out because this is the patient's own capacitous decision about his own treatment; family agreement is not a legal requirement, though sensitive family communication should be sought.$x$, 5),
('db000000-0000-0000-0000-000000000011', 'A', $x$Document the resuscitation status according to the husband's wishes since he will be the main support during her final days$x$, false, $x$Ruled out because spouses do not have legal authority to override a capacitous patient's own decision.$x$, 1),
('db000000-0000-0000-0000-000000000011', 'B', $x$Document a DNACPR order in line with the patient's own capacitous wishes, while gently exploring and addressing her husband's distress and concerns separately$x$, true, $x$Correct. The patient's own wishes take priority when she has capacity; supporting the husband's distress should happen alongside, not instead of, respecting her decision.$x$, 2),
('db000000-0000-0000-0000-000000000011', 'C', 'Avoid making any decision and leave the resuscitation status undecided until the husband agrees', false, $x$Ruled out because this risks the patient's clear, considered wishes not being respected or documented, and inappropriately gives the husband decisional authority.$x$, 3),
('db000000-0000-0000-0000-000000000011', 'D', $x$Ask the patient to reconsider her decision until it aligns with her husband's wishes$x$, false, 'Ruled out because this pressures the patient rather than respecting her autonomous decision.', 4),
('db000000-0000-0000-0000-000000000011', 'E', 'Document that CPR should be attempted because family disagreement makes DNACPR legally risky', false, $x$Ruled out because a capacitous patient's own considered wish should be respected and documented regardless of family disagreement.$x$, 5),
('db000000-0000-0000-0000-000000000012', 'A', 'Recommend proceeding with a third line of chemotherapy regardless, as stopping treatment may reduce survival', false, 'Ruled out because this contradicts his clearly expressed, informed, capacitous wishes and disregards the likely poor benefit/burden ratio.', 1),
('db000000-0000-0000-0000-000000000012', 'B', 'Refer for a psychiatric assessment to determine if he is competent to decline further treatment, given the significance of the decision', false, 'Ruled out because capacity is presumed in adults and there is no indication of impaired capacity here; routine psychiatric referral is not warranted.', 2),
('db000000-0000-0000-0000-000000000012', 'C', 'Respect his autonomous decision, refer to community and hospice palliative care services for symptom control and support at home, and document his preferences', true, $x$Correct. A capacitous adult's informed decision to decline further chemotherapy should be respected, with referral to appropriate ongoing palliative support.$x$, 3),
('db000000-0000-0000-0000-000000000012', 'D', 'Insist his family must formally consent to his decision before it can be honoured', false, $x$Ruled out because a capacitous adult's own decision does not require family consent.$x$, 4),
('db000000-0000-0000-0000-000000000012', 'E', $x$Document that he has been 'discharged from care' since he has declined further active treatment$x$, false, 'Ruled out because declining chemotherapy does not mean withdrawing from all care; ongoing palliative support should be arranged.', 5),
('db000000-0000-0000-0000-000000000013', 'A', 'Offer regular careful mouth care and small sips of oral fluid as tolerated for comfort, review the appropriateness of clinically assisted hydration on an individualised basis considering her previously expressed wishes and current symptoms, and explain the rationale clearly to the family', true, 'Correct. Basic comfort measures should always continue, while clinically assisted hydration decisions balance previously expressed wishes and current symptoms, with clear family communication.', 1),
('db000000-0000-0000-0000-000000000013', 'B', 'Withhold all oral fluids entirely because she previously stated she did not want IV fluids', false, 'Ruled out because this conflates decisions about clinically assisted hydration with basic oral comfort care, which should always be offered.', 2),
('db000000-0000-0000-0000-000000000013', 'C', 'Start IV fluids immediately to prevent family distress, overriding her previously expressed wishes', false, 'Ruled out because her previously expressed wishes about clinically assisted hydration should still guide decisions; family distress should be addressed through communication.', 3),
('db000000-0000-0000-0000-000000000013', 'D', 'Do not discuss the rationale with the family, since hydration decisions in dying patients do not need to be explained', false, 'Ruled out because clear, compassionate communication about hydration decisions is essential to reduce family distress.', 4),
('db000000-0000-0000-0000-000000000013', 'E', 'Assume her previously expressed wish is no longer applicable because she is now asking for water while confused, and therefore start unrestricted IV fluids', false, 'Ruled out because this does not appropriately weigh her earlier considered statement against transient requests during fluctuating delirium; comfort-focused oral care remains appropriate regardless.', 5),
('db000000-0000-0000-0000-000000000014', 'A', '120mg diamorphine subcutaneously over 24 hours', false, 'Ruled out because this uses the oral dose unchanged, failing to account for the increased potency of subcutaneous diamorphine relative to oral morphine.', 1),
('db000000-0000-0000-0000-000000000014', 'B', '60mg diamorphine subcutaneously over 24 hours', false, $x$Ruled out because this applies the oral morphine to subcutaneous morphine conversion factor (divide by 2) rather than the diamorphine-specific factor (divide by 3), underestimating diamorphine's relative potency.$x$, 2),
('db000000-0000-0000-0000-000000000014', 'C', '20mg diamorphine subcutaneously over 24 hours', false, 'Ruled out because this dose is too low and would likely result in inadequate analgesia and a pain crisis, going well beyond the correct conversion.', 3),
('db000000-0000-0000-0000-000000000014', 'D', '240mg diamorphine subcutaneously over 24 hours', false, 'Ruled out because this doubles the oral dose rather than correctly reducing it, risking severe opioid toxicity.', 4),
('db000000-0000-0000-0000-000000000014', 'E', '40mg diamorphine subcutaneously over 24 hours', true, 'Correct. The standard conversion factor from total 24-hour oral morphine dose to subcutaneous diamorphine is to divide by 3 (120mg / 3 = 40mg).', 5),
('db000000-0000-0000-0000-000000000015', 'A', '40mg subcutaneous morphine over 24 hours', false, 'Ruled out because this applies the diamorphine conversion factor (divide by 3) to morphine, which is incorrect.', 1),
('db000000-0000-0000-0000-000000000015', 'B', '120mg subcutaneous morphine over 24 hours', false, 'Ruled out because using the oral dose unchanged ignores the increased bioavailability of the subcutaneous route relative to oral.', 2),
('db000000-0000-0000-0000-000000000015', 'C', '30mg subcutaneous morphine over 24 hours', false, 'Ruled out because this underdoses the patient substantially below the correct divide-by-2 equivalent.', 3),
('db000000-0000-0000-0000-000000000015', 'D', '60mg subcutaneous morphine over 24 hours', true, 'Correct. The oral morphine to subcutaneous morphine conversion factor is divide by 2 (120mg / 2 = 60mg).', 4),
('db000000-0000-0000-0000-000000000015', 'E', '90mg subcutaneous morphine over 24 hours', false, 'Ruled out because this does not correspond to a standard recognised conversion factor and would risk under-treatment relative to the correct dose.', 5),
('db000000-0000-0000-0000-000000000016', 'A', '80mg subcutaneous oxycodone over 24 hours', false, 'Ruled out because this uses the oral dose unchanged, ignoring the greater potency of the parenteral route.', 1),
('db000000-0000-0000-0000-000000000016', 'B', '40mg subcutaneous oxycodone over 24 hours', false, 'Ruled out because this applies a divide-by-2 factor (used for morphine) rather than the oxycodone-specific divide-by-1.5 factor, underdosing the patient.', 2),
('db000000-0000-0000-0000-000000000016', 'C', '27mg subcutaneous oxycodone over 24 hours', false, 'Ruled out because this applies a divide-by-3 factor (used for diamorphine), which would underdose oxycodone significantly.', 3),
('db000000-0000-0000-0000-000000000016', 'D', 'Approximately 53mg subcutaneous oxycodone over 24 hours', true, 'Correct. The oral to subcutaneous oxycodone conversion factor is approximately divide by 1.5 (80mg / 1.5 = ~53mg).', 4),
('db000000-0000-0000-0000-000000000016', 'E', '160mg subcutaneous oxycodone over 24 hours', false, 'Ruled out because this doubles rather than reduces the oral dose, risking significant opioid toxicity.', 5),
('db000000-0000-0000-0000-000000000017', 'A', 'The syringe driver should be started immediately at the full calculated equivalent dose without dose reduction, since removing the patch stops all further fentanyl absorption instantly', false, 'Ruled out because fentanyl continues to be released from the subcutaneous skin depot for many hours after patch removal.', 1),
('db000000-0000-0000-0000-000000000017', 'B', 'Because fentanyl continues to be absorbed from the skin depot for many hours after patch removal, the syringe driver should typically be started at a reduced rate initially, with the full calculated dose only reached after 12-17 hours, alongside close monitoring for toxicity', true, 'Correct. Residual transdermal fentanyl absorption after patch removal creates a real risk of additive toxicity if the full new dose is started immediately.', 2),
('db000000-0000-0000-0000-000000000017', 'C', 'No dose adjustment or monitoring is needed because switching from fentanyl to diamorphine does not require any special caution', false, 'Ruled out because opioid switches, especially involving a fentanyl patch, always require careful equianalgesic calculation and monitoring.', 3),
('db000000-0000-0000-0000-000000000017', 'D', $x$A new patch should be applied at a higher strength before the syringe driver is started, to 'bridge' the gap$x$, false, 'Ruled out because this does not address the actual problem (erratic absorption), and combining continued patch use with a new syringe driver risks unpredictable dosing/toxicity.', 4),
('db000000-0000-0000-0000-000000000017', 'E', 'The diamorphine syringe driver dose should be calculated as double the equivalent oral morphine dose to compensate for the delayed onset', false, 'Ruled out because this misunderstands the pharmacokinetic issue; the concern is residual delayed fentanyl absorption causing toxicity, not a need to double the diamorphine dose.', 5),
('db000000-0000-0000-0000-000000000018', 'A', '45mg subcutaneously as required', false, 'Ruled out because this represents half the total daily dose, far in excess of the standard one-sixth breakthrough calculation.', 1),
('db000000-0000-0000-0000-000000000018', 'B', '5mg subcutaneously as required', false, 'Ruled out because this dose is too low relative to the one-sixth calculation and is likely to be an inadequate breakthrough dose.', 2),
('db000000-0000-0000-0000-000000000018', 'C', '15mg subcutaneously as required', true, 'Correct. The breakthrough dose is calculated as approximately one-sixth of the total 24-hour dose (90mg / 6 = 15mg).', 3),
('db000000-0000-0000-0000-000000000018', 'D', '90mg subcutaneously as required', false, 'Ruled out because this equals the entire 24-hour background dose given as a single breakthrough dose, risking severe overdose.', 4),
('db000000-0000-0000-0000-000000000018', 'E', '30mg subcutaneously as required', false, 'Ruled out because this represents one-third of the total daily dose, roughly double the recommended one-sixth breakthrough calculation.', 5),
('db000000-0000-0000-0000-000000000019', 'A', 'Reduce or stop the morphine infusion and switch to an opioid with less dependence on renal excretion of active metabolites, such as fentanyl or alfentanil, at an appropriately calculated reduced dose', true, $x$Correct. Morphine's active metabolite (morphine-6-glucuronide) accumulates in renal impairment causing neurotoxicity; fentanyl/alfentanil are preferred in significant renal impairment.$x$, 1),
('db000000-0000-0000-0000-000000000019', 'B', 'Increase the morphine infusion rate, as the myoclonus indicates inadequate analgesia', false, 'Ruled out because myoclonus, hallucinations and drowsiness in this context represent opioid-induced neurotoxicity, not undertreated pain; increasing the dose would worsen toxicity.', 2),
('db000000-0000-0000-0000-000000000019', 'C', 'Continue the morphine infusion at the same rate and add an antipsychotic to manage the hallucinations without addressing the opioid dose', false, 'Ruled out because this does not address the underlying cause (opioid toxicity from metabolite accumulation) and could mask worsening toxicity.', 3),
('db000000-0000-0000-0000-000000000019', 'D', 'Switch immediately to an equivalent dose of oral morphine to reduce parenteral absorption', false, $x$Ruled out because this does not address the core problem, renal accumulation of morphine's active metabolites regardless of route, and is impractical in a drowsy patient.$x$, 4),
('db000000-0000-0000-0000-000000000019', 'E', 'Attribute the symptoms to disease progression and continue current management unchanged, as no intervention is needed', false, 'Ruled out because this represents reversible opioid-induced neurotoxicity requiring active intervention, not passive observation.', 5),
('db000000-0000-0000-0000-000000000020', 'A', 'There are no significant compatibility concerns, and all three drugs can always be safely combined in any syringe driver at any concentration', false, 'Ruled out because dexamethasone combined with cyclizine has a recognised risk of precipitation.', 1),
('db000000-0000-0000-0000-000000000020', 'B', 'Diamorphine and cyclizine are the incompatible combination, while dexamethasone is always safe to combine with either', false, 'Ruled out because this misidentifies which pairing carries the well-recognised precipitation risk; cyclizine with dexamethasone is the classic incompatible combination.', 2),
('db000000-0000-0000-0000-000000000020', 'C', 'Cyclizine should never be given by any route in palliative care due to safety concerns', false, 'Ruled out because cyclizine remains a commonly used antiemetic in palliative care; the issue here is specifically syringe driver compatibility, not a contraindication to its use altogether.', 3),
('db000000-0000-0000-0000-000000000020', 'D', 'Compatibility is not a relevant consideration once drugs are drawn up together, as any resulting precipitate is not clinically significant', false, 'Ruled out because visible precipitation indicates a real physical incompatibility that can affect drug delivery and should not be dismissed.', 4),
('db000000-0000-0000-0000-000000000020', 'E', 'Dexamethasone is likely to be physically incompatible with cyclizine in the same syringe, particularly at higher diamorphine concentrations, often causing visible precipitation, and should generally be given as a separate dose rather than combined in the driver', true, 'Correct. Dexamethasone with cyclizine (and diamorphine at higher concentration) is a classic incompatible combination that commonly precipitates.', 5),
('db000000-0000-0000-0000-000000000021', 'A', 'Methadone conversion follows a simple fixed linear ratio regardless of the total prior opioid dose', false, 'Ruled out because methadone conversion ratios are non-linear, unlike the simpler fixed-ratio conversions used for other opioids.', 1),
('db000000-0000-0000-0000-000000000021', 'B', 'Methadone has a long and highly variable half-life with a non-linear relationship to the equivalent dose of the previous opioid, so conversion ratios change according to the total prior opioid dose, and initiation requires specialist supervision with slow titration due to risk of delayed accumulation and toxicity', true, 'Correct. Methadone conversion ratios are non-linear and increase at higher prior opioid doses, and its long variable half-life risks delayed toxicity, requiring specialist initiation.', 2),
('db000000-0000-0000-0000-000000000021', 'C', 'Methadone has a very short half-life, meaning steady state and toxicity risk are reached within hours of a dose change', false, 'Ruled out because methadone has a long and variable half-life, meaning steady state is reached slowly and delayed toxicity can develop over several days.', 3),
('db000000-0000-0000-0000-000000000021', 'D', 'Methadone titration can be safely performed rapidly in the community by non-specialist teams using standard opioid conversion tables', false, $x$Ruled out because methadone's complex pharmacokinetics mean initiation and titration should be supervised by clinicians experienced in its use.$x$, 4),
('db000000-0000-0000-0000-000000000021', 'E', 'Methadone should never be used for cancer pain under any circumstances due to unpredictable pharmacokinetics', false, 'Ruled out because methadone has an established role as a second/third-line opioid in refractory cancer pain when used with appropriate specialist expertise.', 5),
('db000000-0000-0000-0000-000000000022', 'A', $x$Oral morphine should be started at the full calculated dose immediately upon patch removal with no need for caution, since buprenorphine's effect ceases the moment the patch is removed$x$, false, 'Ruled out because buprenorphine continues to be absorbed from the subcutaneous depot for a prolonged period after patch removal.', 1),
('db000000-0000-0000-0000-000000000022', 'B', $x$Buprenorphine and morphine cannot be safely sequenced at all because buprenorphine is a partial agonist that will block morphine's effect$x$, false, 'Ruled out because sequential switching from buprenorphine to a full agonist opioid such as morphine is done routinely following appropriate switching guidance.', 2),
('db000000-0000-0000-0000-000000000022', 'C', 'No conversion calculation or dose adjustment is needed, as buprenorphine and morphine are considered interchangeable milligram-for-milligram', false, 'Ruled out because buprenorphine is many times more potent than morphine and dedicated conversion tables must be used.', 3),
('db000000-0000-0000-0000-000000000022', 'D', 'After removing the buprenorphine patch, its effect persists for many hours as it continues to be absorbed from the skin depot, so the first dose of the new opioid regimen should typically be delayed and/or started cautiously to avoid additive effects, following recognised switching guidance', true, 'Correct. Like fentanyl, buprenorphine continues to be absorbed from its transdermal depot for a considerable period after patch removal.', 4),
('db000000-0000-0000-0000-000000000022', 'E', $x$The patch should be left in place indefinitely alongside the new oral morphine to 'cover the gap,' with both continued together long-term$x$, false, 'Ruled out because running two long-acting opioid systems together indefinitely risks unpredictable toxicity; the patch should be removed as part of a planned switch.', 5),
('db000000-0000-0000-0000-000000000023', 'A', 'Recognise this as likely opioid-induced neurotoxicity, consider reducing the opioid dose and/or switching to an alternative opioid, ensure adequate hydration, and reassess whether the recent escalations were genuinely required or driven by other distress', true, 'Correct. Myoclonus, hallucinations and agitation in this context are hallmark features of opioid neurotoxicity requiring dose reduction/switching and reassessment, not further escalation.', 1),
('db000000-0000-0000-0000-000000000023', 'B', 'Continue escalating the diamorphine dose further, as the myoclonus suggests pain is still undertreated', false, 'Ruled out because further escalation would worsen the opioid toxicity picture rather than treat undertreated pain.', 2),
('db000000-0000-0000-0000-000000000023', 'C', 'Add regular benzodiazepines to control the myoclonus while continuing to increase the opioid dose', false, 'Ruled out because this addresses a symptom rather than its underlying reversible cause, and continued escalation is inappropriate.', 3),
('db000000-0000-0000-0000-000000000023', 'D', 'Attribute the presentation solely to disease progression and terminal decline, and make no changes to management', false, 'Ruled out because this presentation is a recognised, often reversible drug-related complication that should prompt active reassessment.', 4),
('db000000-0000-0000-0000-000000000023', 'E', 'Switch immediately to a much higher dose of an alternative opioid without recalculating an equianalgesic reduction', false, 'Ruled out because opioid switching should use an appropriately calculated, often reduced, equianalgesic dose because of incomplete cross-tolerance.', 5),
('db000000-0000-0000-0000-000000000024', 'A', 'Fentanyl patch 12 micrograms/hour', false, 'Ruled out because this strength corresponds to a much lower oral morphine-equivalent dose (around 30-45mg/24h), a substantial underdose for this patient.', 1),
('db000000-0000-0000-0000-000000000024', 'B', 'Fentanyl patch 25 micrograms/hour', false, 'Ruled out because this strength corresponds to a lower oral morphine-equivalent dose (around 60-90mg/24h), which would underdose this patient.', 2),
('db000000-0000-0000-0000-000000000024', 'C', 'Fentanyl patch 100 micrograms/hour', false, 'Ruled out because this strength corresponds to a considerably higher oral morphine-equivalent dose (around 300-360mg/24h), which would overdose this patient.', 3),
('db000000-0000-0000-0000-000000000024', 'D', 'Fentanyl patch 75 micrograms/hour', false, 'Ruled out because this strength corresponds to a higher oral morphine-equivalent dose than 180mg/24h and would represent an overdose relative to her stable requirement.', 4),
('db000000-0000-0000-0000-000000000024', 'E', 'Fentanyl patch 50 micrograms/hour', true, 'Correct. Published conversion tables generally equate an oral morphine dose around 180mg/24h to a fentanyl patch of approximately 50 micrograms/hour.', 5),
('db000000-0000-0000-0000-000000000025', 'A', 'Water for injection should never be used as a diluent for diamorphine-containing syringe drivers; 0.9% sodium chloride must always be used instead', false, 'Ruled out because water for injection is generally the preferred diluent for diamorphine to help maintain solubility, particularly at higher concentrations.', 1),
('db000000-0000-0000-0000-000000000025', 'B', 'Any combination of three or more drugs in a syringe driver is inherently unsafe and should never be attempted regardless of the specific agents involved', false, 'Ruled out because multi-drug combinations are common and appropriate provided compatibility has been checked for the specific agents, doses and diluent used.', 2),
('db000000-0000-0000-0000-000000000025', 'C', 'Diamorphine, haloperidol and midazolam are generally considered compatible together in a syringe driver at standard concentrations using water for injection as the diluent, and this is a commonly used combination for pain, nausea/agitation and terminal restlessness, but a local compatibility reference should still be checked given the specific doses used', true, 'Correct. This is a well-established, generally compatible combination, though checking current local compatibility guidance for the specific doses remains good practice.', 3),
('db000000-0000-0000-0000-000000000025', 'D', 'Midazolam and haloperidol are absolutely incompatible with each other and can never be combined in the same infusion', false, 'Ruled out because midazolam and haloperidol are commonly combined together with diamorphine in palliative syringe drivers and are generally considered compatible at standard doses.', 4),
('db000000-0000-0000-0000-000000000025', 'E', 'Compatibility does not need to be checked because all drugs used in palliative care syringe drivers are compatible with one another by default', false, 'Ruled out because compatibility is drug-, concentration- and diluent-specific, and some combinations, such as dexamethasone with cyclizine, are well known to be incompatible.', 5),
('db000000-0000-0000-0000-000000000026', 'A', 'Continue the syringe driver unchanged and simply continue prescribing the same breakthrough dose, since the breakthroughs are providing adequate relief', false, 'Ruled out because repeated need for multiple effective breakthrough doses clearly indicates the background dose should be increased.', 1),
('db000000-0000-0000-0000-000000000026', 'B', 'Increase the syringe driver rate to account for the additional opioid required (approximately 60mg background plus 50mg from breakthroughs, rounded to a practical dose such as 100-120mg/24h), and recalculate the new breakthrough dose accordingly', true, 'Correct. Regular need for multiple effective breakthrough doses indicates the background dose is insufficient and should be increased, with the breakthrough dose recalculated as one-sixth of the new total.', 2),
('db000000-0000-0000-0000-000000000026', 'C', 'Reduce the syringe driver rate because the patient is already receiving substantial additional opioid via breakthroughs', false, 'Ruled out because this would worsen background pain control; the correct response to frequent effective breakthroughs is to increase the background rate.', 3),
('db000000-0000-0000-0000-000000000026', 'D', $x$Switch to a completely different opioid because the current one is 'not working,' despite the breakthroughs providing good relief$x$, false, 'Ruled out because the diamorphine is clearly still effective; the issue is background dose insufficiency, not drug choice.', 4),
('db000000-0000-0000-0000-000000000026', 'E', 'Stop the breakthrough prescription entirely and rely solely on the fixed background rate, regardless of ongoing pain', false, 'Ruled out because breakthrough medication should always remain available and appropriately dosed alongside a background infusion.', 5),
('db000000-0000-0000-0000-000000000027', 'A', 'Continue increasing the opioid dose further regardless of worsening side effects, as this is the only available option for pancreatic cancer pain', false, 'Ruled out because escalating an opioid producing worsening toxicity without adequate benefit is not appropriate when an effective interventional option exists.', 1),
('db000000-0000-0000-0000-000000000027', 'B', 'Switch to a purely NSAID-based regimen and discontinue opioids entirely, as NSAIDs are most effective for visceral pancreatic pain', false, 'Ruled out because NSAIDs alone are not an appropriate substitute for opioids in this severe visceral pain syndrome, and abrupt discontinuation would risk withdrawal.', 2),
('db000000-0000-0000-0000-000000000027', 'C', 'Refer for coeliac plexus block (neurolysis), which can provide substantial and sustained relief of visceral pancreatic cancer pain and allow subsequent reduction in systemic opioid requirements', true, 'Correct. Coeliac plexus block is a recognised, effective interventional technique for refractory visceral pancreatic cancer pain.', 3),
('db000000-0000-0000-0000-000000000027', 'D', 'Refer for major open surgical resection specifically to relieve pain, despite the tumour being unresectable', false, 'Ruled out because the tumour has already been assessed as unresectable; surgery is not the appropriate route to pain control here.', 4),
('db000000-0000-0000-0000-000000000027', 'E', 'Recommend acupuncture as the primary next step in preference to interventional or further pharmacological options', false, 'Ruled out because this is not the appropriate primary next step for severe, escalating, opioid-refractory visceral cancer pain when a recognised effective interventional technique is available.', 5),
('db000000-0000-0000-0000-000000000028', 'A', 'A further increase in opioid dose alone, without adding an adjuvant', false, 'Ruled out because neuropathic pain is characteristically only partially opioid-responsive, and adjuvant neuropathic agents are more appropriate than opioid dose escalation alone.', 1),
('db000000-0000-0000-0000-000000000028', 'B', 'A high-dose NSAID as the primary additional agent, as NSAIDs are the treatment of choice for neuropathic pain', false, 'Ruled out because NSAIDs primarily target inflammatory/bone pain mechanisms and are not first-line for neuropathic pain.', 2),
('db000000-0000-0000-0000-000000000028', 'C', 'A bisphosphonate, as this is first-line for all cancer-related pain syndromes', false, 'Ruled out because bisphosphonates are used for bone metastasis-related pain, not for neuropathic pain from plexus infiltration.', 3),
('db000000-0000-0000-0000-000000000028', 'D', 'A neuropathic agent such as amitriptyline, gabapentin, pregabalin, or duloxetine', true, 'Correct. Burning, shooting pain with allodynia in a nerve/plexus infiltration distribution is characteristic of neuropathic pain, which responds better to neuropathic adjuvants than to opioid dose escalation alone.', 4),
('db000000-0000-0000-0000-000000000028', 'E', 'A short course of high-dose oral antibiotics, as neuropathic-type pain suggests an underlying infective plexopathy', false, 'Ruled out because there is no indication of infection here; the pain pattern reflects tumour infiltration of neural structures, not infection.', 5),
('db000000-0000-0000-0000-000000000029', 'A', 'Long-term high-dose oral corticosteroids as the primary treatment for bone pain', false, 'Ruled out because corticosteroids may provide adjunctive benefit but are not the primary/definitive treatment for localised painful bone metastases.', 1),
('db000000-0000-0000-0000-000000000029', 'B', 'A course of broad-spectrum antibiotics, as bone pain in this context suggests underlying osteomyelitis', false, 'Ruled out because there is no clinical suggestion of infection; this represents cancer-related bone pain from lytic metastases.', 2),
('db000000-0000-0000-0000-000000000029', 'C', 'Immediate referral for surgical spinal fixation, regardless of the absence of cord compression or instability', false, 'Ruled out because surgical fixation is reserved for spinal instability or cord compression, not straightforward localised metastatic bone pain.', 3),
('db000000-0000-0000-0000-000000000029', 'D', 'Discontinuation of the opioid in favour of radiotherapy alone, since radiotherapy will fully replace the need for analgesia', false, 'Ruled out because radiotherapy is used alongside, not as an automatic replacement for, systemic analgesia.', 4),
('db000000-0000-0000-0000-000000000029', 'E', 'Single-fraction external beam radiotherapy to the symptomatic metastatic sites', true, 'Correct. Single-fraction radiotherapy is highly effective for localised painful bone metastases and is the treatment of choice in the absence of cord compression.', 5),
('db000000-0000-0000-0000-000000000030', 'A', 'Start high-dose dexamethasone immediately and arrange urgent whole-spine MRI to confirm and localise suspected malignant spinal cord compression, in parallel with urgent oncology/spinal referral for consideration of radiotherapy or surgery', true, 'Correct. Malignant spinal cord compression is a time-critical oncological emergency requiring immediate steroids and urgent imaging, with definitive treatment arranged in parallel.', 1),
('db000000-0000-0000-0000-000000000030', 'B', 'Increase the background opioid dose and reassess in 24 hours before considering any imaging', false, 'Ruled out because this presentation is a red flag for spinal cord compression, a time-critical emergency; delaying imaging/treatment risks irreversible paralysis.', 2),
('db000000-0000-0000-0000-000000000030', 'C', 'Arrange an outpatient MRI over the next one to two weeks given her background of known bone metastases', false, 'Ruled out because this presentation requires urgent same-day imaging and immediate high-dose steroids, not routine outpatient scheduling.', 3),
('db000000-0000-0000-0000-000000000030', 'D', 'Give a single dose of a strong opioid for breakthrough pain and discharge with safety-net advice, since her background pain is already managed', false, 'Ruled out because the new neurological symptoms indicate a spinal emergency, not simply a breakthrough pain episode.', 4),
('db000000-0000-0000-0000-000000000030', 'E', 'Wait for definitive radiotherapy or surgical opinion before starting any steroid treatment', false, 'Ruled out because high-dose dexamethasone should be started immediately on clinical suspicion, without waiting for definitive imaging or specialist opinion.', 5),
('db000000-0000-0000-0000-000000000031', 'A', 'Continue increasing the morphine dose further to overcome apparent tolerance', false, 'Ruled out because the presentation suggests accumulating toxicity from renal impairment rather than true tolerance, and further morphine escalation would worsen this.', 1),
('db000000-0000-0000-0000-000000000031', 'B', 'Switch to an opioid with minimal dependence on renal clearance of active metabolites, such as fentanyl or alfentanil, at an appropriately calculated dose, rather than continuing to escalate morphine', true, $x$Correct. Morphine's active metabolites accumulate in significant renal impairment, causing toxicity without proportionate benefit; fentanyl/alfentanil are preferred in severe renal impairment.$x$, 2),
('db000000-0000-0000-0000-000000000031', 'C', 'Switch to regular high-dose NSAIDs as the mainstay of analgesia given renal concerns with opioids', false, 'Ruled out because NSAIDs are relatively contraindicated in significant renal impairment due to risk of further nephrotoxicity.', 3),
('db000000-0000-0000-0000-000000000031', 'D', 'Discontinue all opioids and rely solely on adjuvant non-opioid analgesics', false, 'Ruled out because abrupt discontinuation of opioids in a patient with significant pain risks withdrawal and inadequate analgesia.', 4),
('db000000-0000-0000-0000-000000000031', 'E', 'Continue the same morphine dose and add haloperidol to manage the somnolence and any associated confusion', false, 'Ruled out because this treats a symptom of likely opioid toxicity rather than the underlying cause.', 5),
('db000000-0000-0000-0000-000000000032', 'A', 'Increase the background opioid dose substantially to try to cover this pain, since it is severe', false, 'Ruled out because increasing the continuous background dose to cover a short-lived, movement-triggered pain risks excess sedation at rest without adequately targeting the trigger.', 1),
('db000000-0000-0000-0000-000000000032', 'B', 'Reassure her that nothing further can be done since her background pain is otherwise well controlled', false, 'Ruled out because incident pain is a recognised, manageable pain pattern that should be actively addressed, not dismissed.', 2),
('db000000-0000-0000-0000-000000000032', 'C', 'Recommend strict bed rest and avoidance of all movement and transfers to prevent triggering the pain', false, 'Ruled out because this would risk deconditioning, pressure injury and reduced quality of life.', 3),
('db000000-0000-0000-0000-000000000032', 'D', 'Switch her entirely to a different opioid, as the presence of incident pain suggests her current opioid has failed', false, 'Ruled out because well-controlled background pain indicates the current opioid is working; incident pain requires targeted proactive breakthrough dosing rather than a full switch.', 4),
('db000000-0000-0000-0000-000000000032', 'E', 'Recognise this as incident (movement-related) pain and prescribe a fast-acting breakthrough opioid dose to be taken proactively shortly before anticipated movement or transfers, alongside optimising positioning/handling support', true, 'Correct. Incident pain triggered predictably by specific movements is best managed with pre-emptive breakthrough dosing timed before the triggering activity.', 5),
('db000000-0000-0000-0000-000000000033', 'A', 'Continue escalating opioid doses indefinitely, since persistent pain despite treatment always indicates the current dose is insufficient', false, 'Ruled out because further escalation without addressing likely contributing psychosocial/spiritual distress risks toxicity without proportionate benefit.', 1),
('db000000-0000-0000-0000-000000000033', 'B', 'Refer for further extensive imaging to search for an occult pain-generating lesion before considering any psychosocial intervention', false, 'Ruled out because recent imaging already shows no new lesion; repeating extensive imaging is not the most appropriate next step.', 2),
('db000000-0000-0000-0000-000000000033', 'C', $x$Adopt a holistic 'total pain' approach, involving psychological, social and spiritual support alongside ongoing physical pain management, recognising that unaddressed psychosocial and existential distress can significantly amplify the physical experience of pain$x$, true, $x$Correct. The 'total pain' concept recognises that psychosocial and spiritual distress can amplify physical pain, requiring a holistic multidisciplinary approach.$x$, 3),
('db000000-0000-0000-0000-000000000033', 'D', 'Explain to the patient that his pain must be purely psychological and stop further analgesic titration entirely', false, $x$Ruled out because dismissing pain as 'purely psychological' is inappropriate; physical pain management should continue alongside psychosocial support.$x$, 4),
('db000000-0000-0000-0000-000000000033', 'E', 'Refer for a single specialist pain intervention such as a nerve block without addressing any of the identified psychosocial and spiritual contributors', false, 'Ruled out because addressing the clearly identified psychosocial/spiritual contributors as part of a total pain approach is more appropriate than an isolated procedure.', 5),
('db000000-0000-0000-0000-000000000034', 'A', 'A further increase in pregabalin well beyond standard maximum doses, disregarding usual dosing limits', false, 'Ruled out because escalating beyond established maximum doses is not standard practice and risks toxicity without proven added benefit.', 1),
('db000000-0000-0000-0000-000000000034', 'B', 'Discontinuing all current neuropathic adjuvants and relying solely on opioid dose escalation', false, 'Ruled out because neuropathic pain is characteristically poorly responsive to opioids alone.', 2),
('db000000-0000-0000-0000-000000000034', 'C', 'A trial of a bisphosphonate as the next step for neuropathic pain', false, 'Ruled out because bisphosphonates target bone pain/skeletal complications, not neuropathic pain from plexus invasion.', 3),
('db000000-0000-0000-0000-000000000034', 'D', 'A trial of ketamine as an adjuvant analgesic, under specialist palliative care or pain team supervision', true, 'Correct. Ketamine has a recognised role as an adjuvant for refractory cancer-related neuropathic pain unresponsive to standard first-line adjuvants, though it requires specialist initiation.', 4),
('db000000-0000-0000-0000-000000000034', 'E', 'Referral for immediate amputation of the affected limb to remove the source of pain', false, 'Ruled out because this is a disproportionate, irreversible intervention not indicated for pain arising from brachial plexus tumour invasion.', 5),
('db000000-0000-0000-0000-000000000035', 'A', 'Intrathecal (spinal) analgesia, delivering opioid and/or local anaesthetic directly into the cerebrospinal fluid via an implanted or externalised catheter/pump, allowing effective analgesia at much lower doses with fewer systemic side effects', true, 'Correct. Intrathecal analgesia is an established option for cancer pain refractory to optimised systemic therapy, particularly when systemic side effects limit further escalation.', 1),
('db000000-0000-0000-0000-000000000035', 'B', 'A further large increase in the oral opioid dose despite the described intolerable sedation', false, 'Ruled out because further escalation in the face of dose-limiting sedation is not appropriate.', 2),
('db000000-0000-0000-0000-000000000035', 'C', 'Complete discontinuation of all opioids and reliance on non-pharmacological therapies alone', false, 'Ruled out because abrupt discontinuation of opioids in a patient with this severity of pain risks withdrawal and severe uncontrolled pain.', 3),
('db000000-0000-0000-0000-000000000035', 'D', 'Referral for elective major limb amputation to remove the presumed source of pain', false, 'Ruled out because amputation is disproportionate and unlikely to be effective for diffuse pain in the context of widely metastatic disease.', 4),
('db000000-0000-0000-0000-000000000035', 'E', 'A trial of high-dose oral NSAIDs as the next escalation step, in place of further opioid or interventional strategies', false, 'Ruled out because NSAIDs are not a substitute for opioid or interventional analgesia in this severity of refractory cancer pain.', 5),
('db000000-0000-0000-0000-000000000036', 'A', 'This represents simple constipation and should be managed solely with stimulant laxatives', false, 'Ruled out because tenesmus is driven by local tumour irritation rather than purely reduced stool transit, and requires targeted local/radiotherapeutic management.', 1),
('db000000-0000-0000-0000-000000000036', 'B', 'This represents complete bowel obstruction requiring emergency laparotomy', false, 'Ruled out because the scenario specifically states there is no evidence of complete obstruction.', 2),
('db000000-0000-0000-0000-000000000036', 'C', 'This symptom cannot be improved and patients should simply be reassured that nothing can be done', false, 'Ruled out because tenesmus is a recognised, distressing symptom with several available management strategies.', 3),
('db000000-0000-0000-0000-000000000036', 'D', 'This represents an unrelated anxiety disorder and should be managed with psychological therapy alone, without any local or systemic treatment directed at the rectal tumour', false, 'Ruled out because the primary driver here is physical tumour infiltration causing tenesmus, requiring targeted local/systemic management.', 4),
('db000000-0000-0000-0000-000000000036', 'E', 'This represents tenesmus due to rectal tumour infiltration; management options include topical/rectal corticosteroids or local anaesthetic preparations, and a smooth muscle relaxant such as nifedipine, alongside optimisation of systemic analgesia and consideration of palliative radiotherapy to the rectal tumour', true, 'Correct. Tenesmus from tumour infiltration is a distinct symptom managed with topical treatments, smooth muscle relaxants, systemic analgesia and radiotherapy.', 5),
('db000000-0000-0000-0000-000000000037', 'A', 'NSAIDs are absolutely contraindicated in all patients with any degree of chronic kidney disease and must never be considered', false, 'Ruled out because NSAIDs are not absolutely contraindicated in all CKD but require careful risk-benefit assessment and monitoring.', 1),
('db000000-0000-0000-0000-000000000037', 'B', 'Start a high-dose NSAID without gastroprotection, since his ulcer was successfully treated five years ago and is no longer a relevant risk factor', false, 'Ruled out because a prior peptic ulcer remains a significant risk factor for NSAID-related gastrointestinal bleeding regardless of prior eradication therapy.', 2),
('db000000-0000-0000-0000-000000000037', 'C', 'If an NSAID is used, prescribe it at the lowest effective dose for the shortest necessary duration with co-prescription of a proton pump inhibitor for gastroprotection, monitor renal function closely, and weigh the incremental analgesic benefit against the risks of further renal impairment and gastrointestinal bleeding given his history', true, 'Correct. NSAIDs can add meaningful analgesic benefit for bone pain but require careful risk-benefit assessment, gastroprotection and renal monitoring in a patient with these risk factors.', 3),
('db000000-0000-0000-0000-000000000037', 'D', 'NSAIDs have no meaningful role in bone pain and should never be added regardless of renal or gastrointestinal risk factors', false, 'Ruled out because NSAIDs can provide meaningful additional analgesic benefit for bone pain when risks are appropriately managed.', 4),
('db000000-0000-0000-0000-000000000037', 'E', 'Stop all current analgesia and switch entirely to a regular NSAID as monotherapy for his bone pain', false, 'Ruled out because an NSAID would be considered as an addition to, not a replacement for, his existing opioid-based regimen.', 5),
('db000000-0000-0000-0000-000000000038', 'A', 'Immediate surgical resection of all liver metastases specifically to relieve pain', false, 'Ruled out because with multiple metastases in widely metastatic disease, surgical resection is not an appropriate approach to pain control here.', 1),
('db000000-0000-0000-0000-000000000038', 'B', 'A trial of dexamethasone, which can reduce peritumoural oedema and inflammation contributing to hepatic capsule distension and associated pain', true, 'Correct. Pain from rapid hepatic capsular distension often responds well to corticosteroids, which reduce peritumoural oedema and inflammation, as an adjunct to opioid analgesia.', 2),
('db000000-0000-0000-0000-000000000038', 'C', 'A trial of a bisphosphonate, as this is the first-line treatment for hepatic capsular pain', false, 'Ruled out because bisphosphonates target bone metastases-related pain, not hepatic capsular distension pain.', 3),
('db000000-0000-0000-0000-000000000038', 'D', 'Discontinuation of opioids in favour of NSAIDs alone, as NSAIDs are more effective for visceral hepatic pain', false, 'Ruled out because NSAIDs are not established as superior to opioids for this pain mechanism and would not be an appropriate replacement.', 4),
('db000000-0000-0000-0000-000000000038', 'E', 'Reassurance only, as pain from liver capsule distension cannot be specifically targeted beyond the existing opioid regimen', false, 'Ruled out because corticosteroids are a specific, evidence-informed adjunct for this pain mechanism and should be tried.', 5),
('db000000-0000-0000-0000-000000000039', 'A', 'Hyoscine butylbromide for colic, dexamethasone to reduce peritumoural oedema and potentially relieve obstruction, an antiemetic such as cyclizine or haloperidol (avoiding prokinetics), and octreotide to reduce gastrointestinal secretions if vomiting remains problematic', true, 'Correct. This is the standard conservative pharmacological approach to inoperable malignant bowel obstruction.', 1),
('db000000-0000-0000-0000-000000000039', 'B', 'Metoclopramide as the first-line antiemetic, given its effectiveness in bowel obstruction', false, 'Ruled out because prokinetic antiemetics such as metoclopramide are generally avoided in complete bowel obstruction as they can worsen colicky pain by increasing peristalsis against an obstruction.', 2),
('db000000-0000-0000-0000-000000000039', 'C', 'A stimulant laxative such as senna to encourage bowel movement past the obstruction', false, 'Ruled out because stimulant laxatives are inappropriate and potentially harmful in bowel obstruction, increasing peristalsis against a blockage and risking perforation.', 3),
('db000000-0000-0000-0000-000000000039', 'D', 'High-dose loperamide to slow gut motility and reduce vomiting', false, 'Ruled out because loperamide is an antimotility agent used for diarrhoea, not an appropriate treatment for malignant bowel obstruction with vomiting.', 4),
('db000000-0000-0000-0000-000000000039', 'E', 'Immediate insertion of a long-term nasogastric tube as the mainstay of ongoing symptom management, without pharmacological measures', false, 'Ruled out because the mainstay of ongoing management in inoperable malignant bowel obstruction is the pharmacological approach described, avoiding the discomfort of prolonged NG tube use where possible.', 5),
('db000000-0000-0000-0000-000000000040', 'A', 'Metoclopramide, as it is the most effective antiemetic for all causes of nausea in palliative care', false, 'Ruled out because metoclopramide is not the preferred choice for nausea due to raised intracranial pressure, where cyclizine acting on the vomiting centre is more appropriate.', 1),
('db000000-0000-0000-0000-000000000040', 'B', 'Ondansetron alone, without any corticosteroid, as the definitive treatment for raised intracranial pressure-related nausea', false, 'Ruled out because the described pattern is more specifically consistent with raised ICP, for which cyclizine plus corticosteroids is the preferred approach.', 2),
('db000000-0000-0000-0000-000000000040', 'C', 'Haloperidol, targeted at chemically/metabolically mediated nausea, as first choice here', false, 'Ruled out because haloperidol is more specifically indicated for nausea due to metabolic or drug-induced causes, which have been reviewed and are not implicated here.', 3),
('db000000-0000-0000-0000-000000000040', 'D', 'Cyclizine, combined with dexamethasone to reduce any associated peritumoural cerebral oedema', true, 'Correct. Nausea due to raised intracranial pressure from brain metastases characteristically responds best to an antihistamine antiemetic such as cyclizine, alongside corticosteroids to reduce cerebral oedema.', 4),
('db000000-0000-0000-0000-000000000040', 'E', 'No antiemetic is required, and only analgesia for the headache should be given', false, 'Ruled out because active nausea and vomiting should be treated, and the underlying likely cause should be specifically addressed with corticosteroids alongside an appropriate antiemetic.', 5),
('db000000-0000-0000-0000-000000000041', 'A', 'Perform frequent deep oropharyngeal suctioning as the primary intervention, as this is generally the most effective and best-tolerated approach', false, 'Ruled out because suctioning is often distressing and provides only temporary relief; it is not the primary recommended approach.', 1),
('db000000-0000-0000-0000-000000000041', 'B', 'Reassure the family that nothing can be done and no intervention is available for this symptom', false, 'Ruled out because several supportive measures can help manage death rattle and support the family.', 2),
('db000000-0000-0000-0000-000000000041', 'C', 'Administer IV fluids to help thin the secretions and make them easier to clear', false, 'Ruled out because additional fluids may worsen rather than improve respiratory secretions in the dying phase.', 3),
('db000000-0000-0000-0000-000000000041', 'D', 'Reposition him to help reduce the noise, consider early treatment with an antimuscarinic such as hyoscine butylbromide or hyoscine hydrobromide (most effective if started promptly once secretions begin), and provide clear, compassionate explanation and reassurance to the family', true, 'Correct. Repositioning and early antimuscarinic treatment, alongside family reassurance, is the standard approach; antimuscarinics prevent further secretion production rather than clearing existing secretions.', 4),
('db000000-0000-0000-0000-000000000041', 'E', 'Withhold antimuscarinic medication until secretions have been present and audible for at least 24 hours, since early treatment provides no benefit', false, 'Ruled out because antimuscarinic drugs prevent further secretion production, so earlier initiation tends to be more effective than delayed treatment.', 5),
('db000000-0000-0000-0000-000000000042', 'A', 'Increase inhaled bronchodilator and corticosteroid doses well beyond standard maximum doses, as this is the only evidence-based option', false, 'Ruled out because exceeding standard maximum inhaled therapy doses is not an appropriate or evidence-based strategy once optimised standard therapy has already failed.', 1),
('db000000-0000-0000-0000-000000000042', 'B', 'Introduce low-dose regular or as-required oral opioids to reduce the sensation of breathlessness, consider a benzodiazepine for the associated anxiety component, and use non-pharmacological measures such as a handheld fan directed at the face', true, 'Correct. Low-dose opioids are evidence-based for refractory breathlessness, and benzodiazepines can help the anxiety component, alongside simple measures such as a fan.', 2),
('db000000-0000-0000-0000-000000000042', 'C', 'Commence high-flow oxygen therapy regardless of oxygen saturation, as oxygen is effective for all causes of breathlessness in advanced disease', false, 'Ruled out because supplemental oxygen has not been shown to reliably improve breathlessness in non-hypoxaemic patients.', 3),
('db000000-0000-0000-0000-000000000042', 'D', 'Avoid opioids entirely due to concern about respiratory depression, and manage with reassurance alone', false, 'Ruled out because low-dose opioids, carefully titrated, have a well-established evidence base for symptomatic relief of refractory breathlessness with low risk of clinically significant respiratory depression at these doses.', 4),
('db000000-0000-0000-0000-000000000042', 'E', 'Treat only the anxiety component with high-dose benzodiazepines, without addressing the breathlessness itself pharmacologically', false, 'Ruled out because breathlessness itself should also be directly addressed, rather than treating anxiety alone with high-dose benzodiazepine.', 5),
('db000000-0000-0000-0000-000000000043', 'A', 'Assess for and address the likely reversible cause of her agitation, urinary retention, for example with catheterisation, before assuming this represents terminal agitation requiring sedation', true, 'Correct. New agitation in the dying phase should always prompt a search for reversible contributing causes before attributing it to terminal restlessness and escalating sedative medication.', 1),
('db000000-0000-0000-0000-000000000043', 'B', 'Immediately increase the midazolam dose in her syringe driver without further assessment, since restlessness at the end of life should be managed with sedation', false, 'Ruled out because a clearly reversible and easily treatable cause has been identified and should be addressed first.', 2),
('db000000-0000-0000-0000-000000000043', 'C', 'Add haloperidol to the syringe driver as the first-line intervention without examining her for reversible causes', false, 'Ruled out because examination has already revealed a likely reversible cause that should be addressed before adding further medication.', 3),
('db000000-0000-0000-0000-000000000043', 'D', 'Assume this represents inevitable, unmanageable terminal agitation and provide reassurance to family without any intervention', false, 'Ruled out because a specific, treatable contributing cause has been identified on examination and should be actively managed.', 4),
('db000000-0000-0000-0000-000000000043', 'E', 'Restrain her physically to prevent injury from her restlessness, without further clinical assessment', false, 'Ruled out because physical restraint is not an appropriate first response and does not address the underlying reversible cause.', 5),
('db000000-0000-0000-0000-000000000044', 'A', 'Continue with hospital-based large-volume paracentesis indefinitely, as no alternative exists for recurrent malignant ascites', false, 'Ruled out because a long-term indwelling peritoneal catheter is a recognised alternative that can be managed in the community.', 1),
('db000000-0000-0000-0000-000000000044', 'B', 'Start high-dose loop diuretics as the definitive treatment, as diuretics reliably control malignant ascites in the same way as ascites due to portal hypertension', false, 'Ruled out because malignant ascites generally responds poorly to diuretics, unlike ascites from cirrhotic portal hypertension.', 2),
('db000000-0000-0000-0000-000000000044', 'C', 'Consider insertion of a long-term indwelling peritoneal catheter, allowing intermittent drainage at home by community/district nursing teams rather than repeated hospital-based paracentesis', true, 'Correct. A long-term indwelling peritoneal catheter is an established option for recurrent symptomatic malignant ascites requiring frequent drainage, reducing hospital attendances.', 3),
('db000000-0000-0000-0000-000000000044', 'D', 'Recommend fluid restriction as the primary strategy to reduce ascites reaccumulation', false, 'Ruled out because fluid restriction is not an effective or appropriate primary strategy for managing malignant ascites.', 4),
('db000000-0000-0000-0000-000000000044', 'E', 'Proceed to insertion of a peritoneovenous shunt as the first-line option ahead of a tunnelled drainage catheter, given her recurrent presentations', false, 'Ruled out because peritoneovenous shunts carry significant complication risks and are not generally first-line compared with a long-term indwelling catheter.', 5),
('db000000-0000-0000-0000-000000000045', 'A', 'Increase the cholestyramine dose further, as higher doses will eventually control cholestasis-related pruritus regardless of the underlying obstruction', false, 'Ruled out because cholestyramine relies on bile acids reaching the gut lumen and is often ineffective in complete biliary obstruction.', 1),
('db000000-0000-0000-0000-000000000045', 'B', 'Start high-dose sedating antihistamines as the definitive, most effective treatment for cholestatic pruritus', false, 'Ruled out because antihistamines are generally poorly effective for cholestasis-related pruritus, which is not primarily histamine-mediated.', 2),
('db000000-0000-0000-0000-000000000045', 'C', 'Recommend hot baths and increased environmental warmth to soothe the itching', false, 'Ruled out because heat and overheating typically worsen pruritus; cooler environments and lukewarm bathing are generally recommended.', 3),
('db000000-0000-0000-0000-000000000045', 'D', 'Reassure him that nothing further can be done since cholestyramine has already failed', false, 'Ruled out because several recognised second-line pharmacological options exist for cholestasis-related pruritus refractory to cholestyramine.', 4),
('db000000-0000-0000-0000-000000000045', 'E', 'Consider a trial of rifampicin or sertraline, both of which have evidence for cholestasis-associated pruritus refractory to cholestyramine, alongside general skin care measures', true, 'Correct. When cholestyramine fails, rifampicin and sertraline are recognised second-line options for cholestatic pruritus.', 5),
('db000000-0000-0000-0000-000000000046', 'A', 'High-dose opioids as the specific first-line treatment for hiccups', false, 'Ruled out because opioids are not an established first-line treatment specifically for hiccups and may even provoke hiccups in some patients.', 1),
('db000000-0000-0000-0000-000000000046', 'B', 'Immediate surgical phrenic nerve division as the first-line intervention', false, 'Ruled out because surgical phrenic nerve interruption is reserved for rare, severely refractory cases after pharmacological options have failed.', 2),
('db000000-0000-0000-0000-000000000046', 'C', 'Chlorpromazine, or alternatively metoclopramide or baclofen, as recognised first-line pharmacological options for persistent hiccups in advanced cancer', true, 'Correct. Chlorpromazine has historically been the most established pharmacological treatment for persistent hiccups, with metoclopramide and baclofen as other commonly used options.', 3),
('db000000-0000-0000-0000-000000000046', 'D', 'Reassurance only, as persistent hiccups in advanced cancer cannot be treated', false, 'Ruled out because several pharmacological options are available and should be tried for this distressing, functionally significant symptom.', 4),
('db000000-0000-0000-0000-000000000046', 'E', 'High-dose benzodiazepines as the specific first-line treatment for hiccups', false, 'Ruled out because benzodiazepines are not an established first-line treatment specifically targeting hiccups.', 5),
('db000000-0000-0000-0000-000000000047', 'A', 'A bulk-forming laxative such as ispaghula husk as the first-line treatment', false, 'Ruled out because bulk-forming laxatives are generally unsuitable for opioid-induced constipation, particularly with reduced oral fluid intake or mobility.', 1),
('db000000-0000-0000-0000-000000000047', 'B', 'Reducing the opioid dose substantially to resolve the constipation, even if this compromises pain control', false, 'Ruled out because opioid-induced constipation should generally be managed with appropriate laxatives rather than compromising analgesia.', 2),
('db000000-0000-0000-0000-000000000047', 'C', 'Reassurance that constipation is an unavoidable and untreatable consequence of opioid therapy', false, 'Ruled out because opioid-induced constipation is a highly predictable, common side effect that should be proactively and effectively managed.', 3),
('db000000-0000-0000-0000-000000000047', 'D', 'Prescribe a regular combination of a stimulant laxative and a softening laxative, started prophylactically alongside opioid therapy and titrated to effect, rather than relying on bulk-forming laxatives', true, 'Correct. Opioid-induced constipation requires a stimulant plus softener combination; bulk-forming laxatives are generally avoided as they can worsen symptoms without adequate fluid intake.', 4),
('db000000-0000-0000-0000-000000000047', 'E', 'A single as-required dose of laxative only if she has not opened her bowels for five or more days', false, 'Ruled out because opioid-induced constipation should be managed with regular, prophylactic laxative therapy, not delayed reactive treatment.', 5),
('db000000-0000-0000-0000-000000000048', 'A', 'Oral calcium-restricted diet alone, without any specific pharmacological treatment', false, 'Ruled out because dietary calcium restriction has minimal impact on hypercalcaemia of malignancy, which is predominantly driven by bone resorption and/or humoral mechanisms.', 1),
('db000000-0000-0000-0000-000000000048', 'B', 'Aggressive intravenous rehydration with 0.9% sodium chloride followed by an intravenous bisphosphonate, which is the definitive treatment for hypercalcaemia of malignancy', true, 'Correct. Initial fluid resuscitation corrects dehydration, which itself worsens hypercalcaemia, and IV bisphosphonate therapy provides sustained calcium-lowering effect by inhibiting osteoclastic bone resorption.', 2),
('db000000-0000-0000-0000-000000000048', 'C', 'Loop diuretics as the primary initial treatment to promote calciuresis', false, 'Ruled out because loop diuretics are not recommended as first-line treatment and can worsen dehydration, which itself exacerbates hypercalcaemia.', 3),
('db000000-0000-0000-0000-000000000048', 'D', 'Immediate haemodialysis as the first-line treatment for this degree of hypercalcaemia with normal renal function', false, 'Ruled out because haemodialysis is reserved for severe hypercalcaemia with renal failure or when standard treatment is contraindicated/ineffective.', 4),
('db000000-0000-0000-0000-000000000048', 'E', 'Withhold all treatment and manage symptomatically only, as hypercalcaemia of malignancy at this level is not treatable', false, 'Ruled out because this represents severe, symptomatic hypercalcaemia of malignancy, an oncological emergency requiring active treatment.', 5),
('db000000-0000-0000-0000-000000000049', 'A', 'Primary adrenal insufficiency, requiring immediate high-dose hydrocortisone replacement', false, 'Ruled out because the scenario states normal adrenal function has been confirmed, making this an unlikely primary mechanism.', 1),
('db000000-0000-0000-0000-000000000049', 'B', 'Simple dehydration, requiring aggressive intravenous 0.9% sodium chloride rehydration', false, 'Ruled out because the patient is euvolaemic, and aggressive saline in true SIADH can worsen hyponatraemia and risks precipitating osmotic demyelination if sodium is corrected too rapidly.', 2),
('db000000-0000-0000-0000-000000000049', 'C', 'Primary hypothyroidism, requiring urgent levothyroxine replacement', false, 'Ruled out because the scenario specifies normal thyroid function.', 3),
('db000000-0000-0000-0000-000000000049', 'D', 'Nephrogenic diabetes insipidus, requiring desmopressin therapy', false, 'Ruled out because the biochemical picture is inconsistent with diabetes insipidus and is instead classic for SIADH.', 4),
('db000000-0000-0000-0000-000000000049', 'E', 'Syndrome of inappropriate antidiuretic hormone secretion (SIADH) due to ectopic ADH production by the small cell lung cancer, initially managed with fluid restriction, with consideration of a vasopressin receptor antagonist or demeclocycline if fluid restriction alone is insufficient, alongside treatment of the underlying cancer', true, 'Correct. This biochemical picture is classic for SIADH, a recognised paraneoplastic complication of small cell lung cancer, initially managed with fluid restriction.', 5),
('db000000-0000-0000-0000-000000000050', 'A', 'Consider insertion of an indwelling pleural catheter, allowing intermittent drainage at home by community nursing teams, as an effective option for managing recurrent symptomatic malignant pleural effusion while supporting his wish to remain at home', true, 'Correct. An indwelling pleural catheter is a well-established option for recurrent malignant pleural effusion, particularly suited to patients who prioritise remaining at home.', 1),
('db000000-0000-0000-0000-000000000050', 'B', 'Repeat simple therapeutic aspiration alone as often as needed, as this is the most appropriate long-term strategy for recurrent malignant pleural effusion', false, 'Ruled out because repeated simple aspiration alone is associated with a high recurrence rate and repeated hospital attendances.', 2),
('db000000-0000-0000-0000-000000000050', 'C', 'Proceed directly to long-term high-dose diuretic therapy as the definitive treatment for malignant pleural effusion', false, 'Ruled out because diuretics are not an effective definitive treatment for malignant pleural effusion.', 3),
('db000000-0000-0000-0000-000000000050', 'D', 'Recommend permanent bed rest and fluid restriction to reduce effusion reaccumulation', false, 'Ruled out because neither bed rest nor fluid restriction is an effective or appropriate strategy for managing malignant pleural effusion.', 4),
('db000000-0000-0000-0000-000000000050', 'E', 'Arrange emergency thoracotomy and pleurectomy as the next step given rapid recurrence', false, 'Ruled out because pleurectomy is a major, invasive surgical procedure not generally appropriate as a routine next step when less invasive options are available.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('db000000-0000-0000-0000-000000000001', $x$Under the Mental Capacity Act 2005, best interests decisions for a patient lacking capacity require consultation with family/carers and consideration of the patient's previously expressed wishes, values and beliefs, not simply agreement from whichever relative pushes hardest.$x$, 1),
('db000000-0000-0000-0000-000000000001', 'The treating clinician holds ultimate responsibility for the best interests decision, but this must be made after proper consultation, not requested from the family as if they were the legal decision-maker.', 2),
('db000000-0000-0000-0000-000000000001', 'Court of Protection involvement is reserved for cases where a best interests process cannot resolve genuine disagreement, or where the decision is highly finely balanced.', 3),
('db000000-0000-0000-0000-000000000002', 'CPR decisions differ from other treatment decisions: a patient with capacity can refuse treatment but cannot demand a treatment (including CPR) that the treating team judges to be clinically futile.', 1),
('db000000-0000-0000-0000-000000000002', 'Good practice requires open, sensitive discussion of the rationale for a DNACPR decision with the patient wherever possible, and an offer of a second opinion if they disagree.', 2),
('db000000-0000-0000-0000-000000000002', 'CPR decisions should be made and documented in real time, not deferred until a patient loses capacity, as this would deprive them of the chance to be involved.', 3),
('db000000-0000-0000-0000-000000000003', 'A valid and applicable ADRT is legally binding under the Mental Capacity Act 2005 and takes precedence over both family wishes and clinician preference, provided it specifically anticipated the situation that has arisen.', 1),
('db000000-0000-0000-0000-000000000003', 'Validity and applicability of an ADRT must be assessed against the circumstances specified at the time it was made; a later loss of capacity does not itself invalidate it.', 2),
('db000000-0000-0000-0000-000000000003', 'Clinicians must consider whether the actual clinical situation falls within the scope the patient described, rather than using a technicality (such as a treatable precipitant) to override their wishes.', 3),
('db000000-0000-0000-0000-000000000004', $x$A registered LPA for health and welfare authorises the attorney to make decisions on the patient's behalf, but attorneys are legally required to act in the patient's best interests, not simply demand any treatment they wish.$x$, 1),
('db000000-0000-0000-0000-000000000004', $x$Clinicians are not obliged to provide treatment that is not clinically indicated or judged not to be in a patient's best interests, even if requested by an attorney; disagreements should be resolved via second opinion, mediation, or ultimately the Court of Protection.$x$, 2),
('db000000-0000-0000-0000-000000000004', $x$Good practice is to explore the reasoning behind the attorney's request and explain honestly why a treatment is not being offered, rather than simply refusing without discussion.$x$, 3),
('db000000-0000-0000-0000-000000000005', 'Capacity is decision-specific and time-specific: a person may lack capacity for a decision at one point in the day and have capacity for the same decision at another point, and assessments should be timed accordingly.', 1),
('db000000-0000-0000-0000-000000000005', $x$Every effort should be made to maximise a person's ability to make their own decision, including timing conversations around symptom control that improves alertness, before concluding they lack capacity.$x$, 2),
('db000000-0000-0000-0000-000000000005', 'The Mental Capacity Act two-stage test (diagnostic and functional) must be applied at the specific time the decision is needed, not assumed from a single earlier presentation.', 3),
('db000000-0000-0000-0000-000000000006', 'Continuing a treatment assessed as clinically futile is not obligatory, but withdrawal decisions should be reached transparently, with honest prognostic communication and, where disagreement persists, a second clinical opinion.', 1),
('db000000-0000-0000-0000-000000000006', $x$Next of kin without a registered LPA do not have legal decision-making authority in England and Wales, but their views and knowledge of the patient's wishes should still be actively sought.$x$, 2),
('db000000-0000-0000-0000-000000000006', 'Early involvement of palliative care alongside organ-support specialists helps align symptom management and family support with an evolving decision about ceiling of care.', 3),
('db000000-0000-0000-0000-000000000007', $x$Malignant spinal cord compression management decisions should be guided by an assessment of overall prognosis, functional status, and realistic likelihood of benefit, not simply by family requests for 'everything possible.'$x$, 1),
('db000000-0000-0000-0000-000000000007', 'Honest, compassionate communication about prognosis and the rationale for treatment decisions helps families process difficult news and reduces conflict, compared with avoiding the conversation.', 2),
('db000000-0000-0000-0000-000000000007', 'Formal escalation to the Court of Protection is reserved for situations where good communication and second opinions cannot resolve a genuine best-interests dispute.', 3),
('db000000-0000-0000-0000-000000000008', 'Proportionate palliative sedation is titrated to relieve otherwise intractable, refractory symptoms at the end of life using the minimum effective dose, and is legally and ethically distinct from euthanasia.', 1),
('db000000-0000-0000-0000-000000000008', 'The doctrine of double effect underpins this distinction: an act with a good primary intent that has a foreseen but unintended secondary effect is ethically and legally different from an act intended to cause death.', 2),
('db000000-0000-0000-0000-000000000008', 'Good practice includes multidisciplinary discussion, exploring reversible contributors first, and clear documentation of intent and titration plan before initiating palliative sedation.', 3),
('db000000-0000-0000-0000-000000000009', 'Following An NHS Trust v Y (2018), Court of Protection authorisation is not required to withdraw clinically assisted nutrition and hydration provided the decision follows established best-interests guidance and there is agreement between the clinical team and those close to the patient.', 1),
('db000000-0000-0000-0000-000000000009', 'An Independent Mental Capacity Advocate must be involved where a patient lacking capacity has no family or friends appropriate to consult about a serious medical treatment decision, not as a mandatory extra step when engaged family are already contributing.', 2),
('db000000-0000-0000-0000-000000000009', 'Court referral remains appropriate where there is a genuine, unresolved dispute, or where the best interests balance is unusually finely poised.', 3),
('db000000-0000-0000-0000-000000000010', 'A patient with capacity has the right to refuse or withdraw consent to any treatment, including a life-sustaining one such as NIV, and this is legally and ethically distinct from euthanasia or assisted suicide.', 1),
('db000000-0000-0000-0000-000000000010', $x$Planned withdrawal of ventilatory support ('terminal weaning') should include anticipatory prescribing of opioids and sedatives to manage breathlessness, distress and secretions as ventilation is reduced.$x$, 2),
('db000000-0000-0000-0000-000000000010', 'Screening for and addressing reversible low mood is good holistic practice, but it is not a legal precondition for honouring a capacitous decision to stop a burdensome treatment.', 3),
('db000000-0000-0000-0000-000000000011', $x$When a patient with capacity has clearly expressed their own wishes about resuscitation, those wishes take priority over the differing views of family members, who do not have legal decision-making authority over a competent adult's treatment.$x$, 1),
('db000000-0000-0000-0000-000000000011', $x$Supporting distressed family members through separate, sensitive conversation is important, but must not override or delay respecting the patient's own documented, capacitous decision.$x$, 2),
('db000000-0000-0000-0000-000000000011', 'DNACPR decisions should be communicated compassionately to both patient and family, clarifying that all other appropriate care continues.', 3),
('db000000-0000-0000-0000-000000000012', 'A patient with capacity has the right to decline any treatment, including further chemotherapy, after being given adequate information, without requiring family consent or routine psychiatric clearance.', 1),
('db000000-0000-0000-0000-000000000012', 'Declining active oncological treatment should prompt referral to palliative care and appropriate community/hospice support, not withdrawal of all care.', 2),
('db000000-0000-0000-0000-000000000012', $x$Advance care planning documentation should reflect the patient's own wishes and be revisited as circumstances evolve.$x$, 3),
('db000000-0000-0000-0000-000000000013', 'Basic comfort measures, including regular mouth care and oral fluids as tolerated, should always be offered to dying patients regardless of decisions about clinically assisted hydration.', 1),
('db000000-0000-0000-0000-000000000013', $x$Decisions about clinically assisted (parenteral) hydration in the dying phase should individually balance the patient's previously expressed wishes, current symptom burden, and evidence of likely benefit or harm.$x$, 2),
('db000000-0000-0000-0000-000000000013', $x$Proactive, honest communication with family about the rationale for hydration decisions at the end of life reduces distress and the perception that the patient is being 'starved' or 'dehydrated.'$x$, 3),
('db000000-0000-0000-0000-000000000014', $x$The standard conversion from total 24-hour oral morphine dose to subcutaneous diamorphine dose is to divide by 3, reflecting diamorphine's greater potency and different pharmacokinetics via the subcutaneous route.$x$, 1),
('db000000-0000-0000-0000-000000000014', 'This differs from the oral morphine to subcutaneous morphine conversion, which uses a divide-by-2 factor; confusing the two conversion factors is a common and dangerous prescribing error.', 2),
('db000000-0000-0000-0000-000000000014', 'Breakthrough subcutaneous doses should typically be calculated as one-sixth of the new 24-hour syringe driver dose, prescribed alongside the driver at the point of conversion.', 3),
('db000000-0000-0000-0000-000000000015', 'Oral morphine is converted to subcutaneous morphine using a divide-by-2 factor, reflecting roughly double the bioavailability of the subcutaneous route compared with oral.', 1),
('db000000-0000-0000-0000-000000000015', 'This is a different (smaller) reduction than that used when converting oral morphine to subcutaneous diamorphine (divide by 3), and the two must not be confused.', 2),
('db000000-0000-0000-0000-000000000015', 'Sites without diamorphine availability commonly use subcutaneous morphine in syringe drivers; the conversion factor used must match the specific opioid being switched to.', 3),
('db000000-0000-0000-0000-000000000016', 'The recognised oral-to-subcutaneous conversion factor for oxycodone is approximately divide by 1.5, distinct from the factors used for morphine (divide by 2) or diamorphine (divide by 3).', 1),
('db000000-0000-0000-0000-000000000016', 'Oxycodone may be a useful alternative to morphine/diamorphine syringe drivers, for example in morphine intolerance or some cases of renal impairment, but local availability of subcutaneous formulations should be checked.', 2),
('db000000-0000-0000-0000-000000000016', 'As with all opioid switches, breakthrough dosing must be recalculated for the new drug and route rather than continuing the previous breakthrough prescription.', 3),
('db000000-0000-0000-0000-000000000017', 'Transdermal fentanyl continues to be absorbed from the subcutaneous skin depot for approximately 12-24 hours after a patch is removed, so switching immediately to a full-dose alternative opioid risks additive toxicity.', 1),
('db000000-0000-0000-0000-000000000017', 'When switching away from a fentanyl patch, it is common practice to start the new opioid at a reduced dose initially, titrating up as the residual fentanyl effect wanes, with close clinical monitoring.', 2),
('db000000-0000-0000-0000-000000000017', 'Erratic or reduced peripheral perfusion can make transdermal opioid absorption unpredictable, which is itself a common reason to switch a patient from a patch to a subcutaneous infusion.', 3),
('db000000-0000-0000-0000-000000000018', 'Breakthrough opioid doses are conventionally calculated as approximately one-sixth (sometimes quoted as one-tenth to one-sixth) of the total 24-hour background opioid dose, using the same drug and route where possible.', 1),
('db000000-0000-0000-0000-000000000018', 'Breakthrough doses must be recalculated every time the background 24-hour dose is changed, since a fixed prior breakthrough dose becomes inappropriate as the driver rate is titrated.', 2),
('db000000-0000-0000-0000-000000000018', 'Frequent use of breakthrough doses should prompt review and likely upward titration of the background syringe driver rate.', 3),
('db000000-0000-0000-0000-000000000019', $x$Morphine's active metabolite, morphine-6-glucuronide, is renally excreted and accumulates in renal impairment, causing opioid-induced neurotoxicity: myoclonus, hallucinations, drowsiness, and hyperalgesia.$x$, 1),
('db000000-0000-0000-0000-000000000019', 'In significant renal impairment, opioids with less dependence on renal clearance of active metabolites, such as fentanyl or alfentanil, are preferred over morphine or diamorphine.', 2),
('db000000-0000-0000-0000-000000000019', 'Opioid-induced neurotoxicity should prompt dose reduction and/or opioid switching rather than simply increasing the dose or masking symptoms with additional sedating drugs.', 3),
('db000000-0000-0000-0000-000000000020', 'Dexamethasone has well-recognised physical incompatibilities with several drugs commonly used in syringe drivers, including cyclizine, and can also become unstable when combined with diamorphine at higher concentrations.', 1),
('db000000-0000-0000-0000-000000000020', 'When incompatibility is a concern, options include giving the incompatible drug separately rather than combining all agents into one syringe.', 2),
('db000000-0000-0000-0000-000000000020', 'Local palliative care compatibility charts should always be checked before combining multiple drugs in a syringe driver, as compatibility depends on the specific combination, concentration and diluent used.', 3),
('db000000-0000-0000-0000-000000000021', $x$Methadone's long, highly variable half-life and non-linear relationship between prior opioid dose and conversion ratio make it markedly different from morphine, oxycodone or diamorphine conversions, which use simple fixed ratios.$x$, 1),
('db000000-0000-0000-0000-000000000021', 'Because of delayed accumulation, methadone initiation carries a real risk of late-onset toxicity that may not become apparent for several days, requiring slow titration and close monitoring.', 2),
('db000000-0000-0000-0000-000000000021', 'Methadone can be particularly useful in opioid-induced hyperalgesia or refractory pain, partly due to additional NMDA-receptor antagonist activity, but should be initiated only under specialist supervision.', 3),
('db000000-0000-0000-0000-000000000022', 'Like fentanyl, buprenorphine continues to be absorbed from its transdermal depot for a considerable period after patch removal, so timing and dose caution are needed when starting the next opioid.', 1),
('db000000-0000-0000-0000-000000000022', 'Buprenorphine is a partial opioid agonist with high receptor affinity and a specific place in potency conversion tables; it is not interchangeable milligram-for-milligram with morphine.', 2),
('db000000-0000-0000-0000-000000000022', 'Opioid switches around patch-based formulations always require attention to residual depot absorption, not just the calculated equianalgesic dose.', 3),
('db000000-0000-0000-0000-000000000023', 'Opioid-induced neurotoxicity can occur with rapidly escalating opioid doses and is often mistaken for inadequately controlled pain, leading to a dangerous cycle of further dose escalation.', 1),
('db000000-0000-0000-0000-000000000023', 'Management involves identifying and correcting reversible contributors, reducing the opioid dose, and/or switching opioids using an appropriately calculated, often reduced, equianalgesic dose.', 2),
('db000000-0000-0000-0000-000000000023', 'Reassessing whether recent dose escalations were genuinely due to nociceptive pain, rather than other forms of distress, is important before further increasing opioid doses.', 3),
('db000000-0000-0000-0000-000000000024', 'Published equianalgesic conversion tables are used to translate a stable total 24-hour oral morphine dose into an appropriate transdermal fentanyl patch strength.', 1),
('db000000-0000-0000-0000-000000000024', 'Because a fentanyl patch takes 12-24 hours to reach therapeutic effect after application, the previous opioid (or equivalent breakthrough cover) must continue to be available during this transition period.', 2),
('db000000-0000-0000-0000-000000000024', $x$Converting to a patch should generally only be done once a patient's opioid requirement is relatively stable, since patches are much less suited to rapid dose titration than oral or parenteral routes.$x$, 3),
('db000000-0000-0000-0000-000000000025', 'Diamorphine, haloperidol and midazolam together are a well-established, generally compatible syringe driver combination for managing pain, nausea and terminal agitation simultaneously.', 1),
('db000000-0000-0000-0000-000000000025', 'Water for injection is generally the preferred diluent for diamorphine-containing syringe drivers, particularly at higher concentrations, to reduce the risk of precipitation.', 2),
('db000000-0000-0000-0000-000000000025', 'Not all combinations are compatible, so compatibility should always be actively checked for each specific combination rather than assumed.', 3),
('db000000-0000-0000-0000-000000000026', 'Frequent, effective use of breakthrough opioid doses is a key indicator that the background dose is insufficient and should be increased to incorporate the additional opioid the patient is actually requiring.', 1),
('db000000-0000-0000-0000-000000000026', 'After any change to the background syringe driver rate, the breakthrough dose must be recalculated (approximately one-sixth of the new total) to remain proportionate.', 2),
('db000000-0000-0000-0000-000000000026', 'A drug that is providing good relief when given as breakthrough is clearly still effective for that patient; the issue in this scenario is dose sufficiency, not choice of opioid.', 3),
('db000000-0000-0000-0000-000000000027', 'Coeliac plexus block/neurolysis is a well-established interventional technique for refractory visceral pain from pancreatic and other upper abdominal cancers, and can significantly reduce systemic opioid requirements and side effects.', 1),
('db000000-0000-0000-0000-000000000027', 'Escalating a systemic opioid indefinitely in the face of worsening toxicity without proportionate analgesic benefit should prompt consideration of alternative or adjunctive approaches.', 2),
('db000000-0000-0000-0000-000000000027', 'Recognising specific pain syndromes that respond particularly well to targeted interventional techniques is an important part of advanced pain management in palliative care.', 3),
('db000000-0000-0000-0000-000000000028', 'Neuropathic pain arising from tumour infiltration of nerves or plexuses is characteristically only partially responsive to opioids alone and benefits from a neuropathic adjuvant such as a tricyclic antidepressant, gabapentinoid, or SNRI.', 1),
('db000000-0000-0000-0000-000000000028', 'Recognising the clinical pattern of neuropathic pain is essential to selecting the correct adjuvant, as different pain mechanisms respond to different treatment strategies.', 2),
('db000000-0000-0000-0000-000000000028', 'Adjuvant analgesics are typically titrated alongside, rather than instead of, ongoing opioid therapy in mixed pain syndromes.', 3),
('db000000-0000-0000-0000-000000000029', 'Single-fraction (or short-course) external beam radiotherapy is highly effective and is the treatment of choice for localised pain from bone metastases, complementing systemic analgesia.', 1),
('db000000-0000-0000-0000-000000000029', 'Bisphosphonates or denosumab may reduce skeletal-related events over time in patients with bone metastases but act more slowly than radiotherapy for acute pain relief.', 2),
('db000000-0000-0000-0000-000000000029', 'Any new or worsening spinal pain in a patient with known bone metastases should prompt assessment for cord compression before assuming straightforward localised bone pain.', 3),
('db000000-0000-0000-0000-000000000030', 'Malignant spinal cord compression is an oncological emergency: any patient with known or suspected bone metastases who develops new back pain with neurological symptoms requires immediate high-dose corticosteroids and urgent whole-spine MRI.', 1),
('db000000-0000-0000-0000-000000000030', 'Definitive treatment should be arranged in parallel with, not delayed until after, initial steroid treatment and imaging, given that neurological outcome is highly time-dependent.', 2),
('db000000-0000-0000-0000-000000000030', 'A sensory level and bilateral leg weakness in a patient with known vertebral metastases are red-flag features that should never be managed simply as a breakthrough pain episode.', 3),
('db000000-0000-0000-0000-000000000031', 'In significant renal impairment, morphine and diamorphine should generally be avoided or used with great caution due to accumulation of active renally-excreted metabolites; fentanyl and alfentanil are preferred alternatives.', 1),
('db000000-0000-0000-0000-000000000031', 'Somnolence and inadequate analgesic benefit despite dose escalation in a patient with renal impairment should raise suspicion of opioid metabolite accumulation rather than simply undertreated pain or tolerance.', 2),
('db000000-0000-0000-0000-000000000031', 'NSAIDs should generally be avoided or used very cautiously in patients with significant renal impairment due to the risk of further nephrotoxicity.', 3),
('db000000-0000-0000-0000-000000000032', 'Incident (movement- or activity-related) pain is a distinct pain pattern from continuous background pain, typically brief, predictable, and triggered by a specific activity.', 1),
('db000000-0000-0000-0000-000000000032', 'The preferred management of incident pain is a fast-onset breakthrough analgesic taken pre-emptively, shortly before the anticipated triggering activity.', 2),
('db000000-0000-0000-0000-000000000032', 'Physical and occupational therapy input can complement pharmacological management of incident pain and help preserve safe mobility.', 3),
('db000000-0000-0000-0000-000000000033', $x$The 'total pain' concept recognises that physical, psychological, social and spiritual factors interact and contribute to a patient's overall experience of pain, particularly in advanced illness.$x$, 1),
('db000000-0000-0000-0000-000000000033', 'Pain that appears disproportionately refractory to escalating analgesia, in the absence of a new physical cause, should prompt assessment of psychosocial and spiritual distress as contributing factors.', 2),
('db000000-0000-0000-0000-000000000033', 'A multidisciplinary approach, alongside medical pain management, is central to addressing total pain effectively.', 3),
('db000000-0000-0000-0000-000000000034', 'Ketamine, an NMDA-receptor antagonist, has an established role as an adjuvant for refractory cancer-related neuropathic pain unresponsive to standard first-line agents, but requires specialist supervision due to psychomimetic side effects.', 1),
('db000000-0000-0000-0000-000000000034', 'Exceeding established maximum doses of standard adjuvants is not appropriate practice; escalation to a different pharmacological class is the appropriate next step.', 2),
('db000000-0000-0000-0000-000000000034', 'A structured, stepwise approach to refractory neuropathic pain is central to advanced pain management in palliative care.', 3),
('db000000-0000-0000-0000-000000000035', 'Intrathecal (spinal) analgesia is a recognised advanced technique for cancer pain refractory despite optimised systemic opioids, adjuvants, and opioid switching, particularly when systemic side effects limit further dose escalation.', 1),
('db000000-0000-0000-0000-000000000035', 'Delivering analgesics directly into the cerebrospinal fluid allows much lower total drug doses to achieve effective analgesia, reducing systemic side effects.', 2),
('db000000-0000-0000-0000-000000000035', 'Advanced interventional pain techniques should be considered in a stepwise fashion once standard systemic and adjuvant options have been optimised and have failed.', 3),
('db000000-0000-0000-0000-000000000036', 'Tenesmus is a distressing sensation of persistent urge to defecate with minimal stool passage, typically due to direct tumour infiltration or irritation of the rectal wall, distinct from constipation or bowel obstruction.', 1),
('db000000-0000-0000-0000-000000000036', 'Management strategies for tenesmus include topical rectal corticosteroids or local anaesthetics, smooth muscle relaxants, optimised systemic analgesia, and palliative radiotherapy.', 2),
('db000000-0000-0000-0000-000000000036', 'Distinguishing tenesmus from constipation and from complete bowel obstruction is important, as each requires a different management approach.', 3),
('db000000-0000-0000-0000-000000000037', 'NSAIDs can provide meaningful additional analgesic benefit for bone pain due to their anti-inflammatory effects at sites of periosteal and bone involvement, used as an adjunct within a multimodal regimen.', 1),
('db000000-0000-0000-0000-000000000037', 'Chronic kidney disease and prior peptic ulcer disease significantly increase the risk of NSAID-related renal impairment and gastrointestinal bleeding, requiring careful risk-benefit assessment, lowest effective dose, and gastroprotection.', 2),
('db000000-0000-0000-0000-000000000037', 'A prior history of peptic ulcer disease remains clinically relevant when considering NSAID therapy even years after apparently successful treatment.', 3),
('db000000-0000-0000-0000-000000000038', 'Pain from hepatic capsule distension due to rapidly growing or bulky liver metastases often has a component of peritumoural oedema and inflammation that responds well to corticosteroids as an adjunct to opioid analgesia.', 1),
('db000000-0000-0000-0000-000000000038', 'Right shoulder-tip pain can be a referred pattern from hepatic/diaphragmatic irritation and should be recognised as part of the same underlying pain mechanism.', 2),
('db000000-0000-0000-0000-000000000038', 'Adjuvant corticosteroids are used across several distinct palliative pain mechanisms, each with a specific rationale for their anti-oedema/anti-inflammatory effect.', 3),
('db000000-0000-0000-0000-000000000039', 'In inoperable malignant bowel obstruction, the standard conservative pharmacological approach combines an antispasmodic for colic, corticosteroids which may reduce peritumoural oedema and occasionally relieve obstruction, an appropriate antiemetic avoiding prokinetics, and octreotide to reduce secretions.', 1),
('db000000-0000-0000-0000-000000000039', 'Prokinetic antiemetics and stimulant laxatives are generally avoided in complete mechanical bowel obstruction because increasing peristalsis against an obstruction can worsen colicky pain and risk perforation.', 2),
('db000000-0000-0000-0000-000000000039', 'Octreotide reduces gastrointestinal secretions via somatostatin-receptor mediated inhibition, particularly useful when vomiting remains problematic despite an antispasmodic and antiemetic.', 3),
('db000000-0000-0000-0000-000000000040', 'Nausea and vomiting due to raised intracranial pressure is characteristically worse in the mornings, may be associated with headache, and responds best to an antihistamine antiemetic such as cyclizine combined with corticosteroids.', 1),
('db000000-0000-0000-0000-000000000040', 'Selecting an antiemetic according to the presumed underlying mechanism is a core principle of palliative antiemetic prescribing.', 2),
('db000000-0000-0000-0000-000000000040', 'A full review of potentially reversible or contributing causes should always be performed before attributing nausea solely to a single mechanism, even when a plausible cause is present.', 3),
('db000000-0000-0000-0000-000000000041', 'Death rattle results from pooled upper airway secretions in a patient too weak to clear them, and antimuscarinic drugs act by reducing further secretion production, so they are more effective when started early.', 1),
('db000000-0000-0000-0000-000000000041', 'Repositioning the patient is a simple, low-risk measure that can reduce the noise of secretions alongside pharmacological treatment.', 2),
('db000000-0000-0000-0000-000000000041', 'Because death rattle is often more distressing to family and staff than to the usually unconscious patient, clear compassionate communication is an essential part of management.', 3),
('db000000-0000-0000-0000-000000000042', 'Low-dose opioids have an established evidence base for symptomatic relief of refractory breathlessness in advanced respiratory and malignant disease, working centrally to reduce the perception of breathlessness.', 1),
('db000000-0000-0000-0000-000000000042', 'Anxiety commonly amplifies the sensation of breathlessness in advanced disease, and a low-dose benzodiazepine can be a useful adjunct alongside opioids and non-pharmacological measures.', 2),
('db000000-0000-0000-0000-000000000042', 'A handheld fan directed at the face is a simple, evidence-supported non-pharmacological measure that can meaningfully reduce the sensation of breathlessness.', 3),
('db000000-0000-0000-0000-000000000043', $x$New agitation or restlessness in a dying patient should always prompt assessment for reversible contributing causes before attributing it to 'terminal agitation' and escalating sedative medication.$x$, 1),
('db000000-0000-0000-0000-000000000043', 'A palpably distended bladder with reduced urine output is a classic, easily treatable cause of new agitation in patients who cannot verbally communicate discomfort.', 2),
('db000000-0000-0000-0000-000000000043', 'Only once reversible causes have been excluded or addressed should escalation of sedative medication be considered for genuine terminal restlessness.', 3),
('db000000-0000-0000-0000-000000000044', 'A long-term indwelling (tunnelled) peritoneal catheter is a well-established option for recurrent symptomatic malignant ascites, allowing intermittent drainage in the community.', 1),
('db000000-0000-0000-0000-000000000044', 'Malignant ascites due to peritoneal carcinomatosis typically responds poorly to diuretics, unlike ascites due to cirrhotic portal hypertension, because the underlying mechanism differs.', 2),
('db000000-0000-0000-0000-000000000044', 'Peritoneovenous shunting is generally reserved as a less preferred option due to its complication profile, compared with indwelling catheter drainage.', 3),
('db000000-0000-0000-0000-000000000045', $x$Cholestyramine's efficacy for cholestatic pruritus depends on adequate bile acid delivery into the gut lumen, and it is often ineffective in complete or unstentable biliary obstruction.$x$, 1),
('db000000-0000-0000-0000-000000000045', 'Rifampicin and sertraline are recognised second-line pharmacological options for cholestasis-associated pruritus refractory to cholestyramine.', 2),
('db000000-0000-0000-0000-000000000045', 'General measures such as emollients, avoiding overheating, and cool bathing are useful adjuncts across most causes of pruritus in palliative care, though they rarely provide complete relief in cholestatic pruritus alone.', 3),
('db000000-0000-0000-0000-000000000046', 'Chlorpromazine has traditionally been regarded as the most established pharmacological treatment for persistent hiccups, with metoclopramide and baclofen as other recognised options.', 1),
('db000000-0000-0000-0000-000000000046', 'Simple non-pharmacological measures should be tried first, but persistent, functionally significant hiccups warrant escalation to pharmacological treatment.', 2),
('db000000-0000-0000-0000-000000000046', 'Identifying a likely contributing mechanism can help guide the choice between the available pharmacological options.', 3),
('db000000-0000-0000-0000-000000000047', 'Opioid-induced constipation results from reduced gastrointestinal motility and increased fluid reabsorption, and should be anticipated and managed prophylactically with a regular stimulant laxative combined with a softening agent.', 1),
('db000000-0000-0000-0000-000000000047', 'Bulk-forming laxatives are generally avoided in opioid-induced constipation, as they risk worsening symptoms without adequate fluid intake.', 2),
('db000000-0000-0000-0000-000000000047', 'If standard laxative combinations fail, a peripherally acting mu-opioid receptor antagonist can be considered as an escalation option.', 3),
('db000000-0000-0000-0000-000000000048', 'Hypercalcaemia of malignancy is managed initially with aggressive intravenous rehydration, followed by an intravenous bisphosphonate for more sustained control via inhibition of osteoclastic bone resorption.', 1),
('db000000-0000-0000-0000-000000000048', 'Loop diuretics are not recommended as first-line treatment for hypercalcaemia and should not be given before adequate rehydration, as they can worsen volume depletion.', 2),
('db000000-0000-0000-0000-000000000048', 'Hypercalcaemia of malignancy is a common oncological emergency, particularly in cancers with extensive bone metastases or humoral mechanisms, and should be actively treated given its significant impact on quality of life.', 3),
('db000000-0000-0000-0000-000000000049', 'SIADH is a well-recognised paraneoplastic complication of small cell lung cancer, typically presenting with euvolaemic hyponatraemia, low serum osmolality, and inappropriately concentrated urine, after excluding renal, adrenal and thyroid causes.', 1),
('db000000-0000-0000-0000-000000000049', 'Initial management of SIADH is fluid restriction, with vasopressin receptor antagonists or demeclocycline considered if fluid restriction alone is insufficient.', 2),
('db000000-0000-0000-0000-000000000049', 'Rapid correction of chronic hyponatraemia risks osmotic demyelination syndrome, so correction should be gradual and carefully monitored.', 3),
('db000000-0000-0000-0000-000000000050', 'An indwelling pleural catheter is a well-established, effective option for recurrent symptomatic malignant pleural effusion, particularly suited to patients wishing to avoid repeated hospital admissions.', 1),
('db000000-0000-0000-0000-000000000050', 'Simple repeated therapeutic aspiration alone is associated with a high rate of rapid recurrence and is not generally an appropriate long-term strategy for a genuinely recurrent malignant effusion.', 2),
('db000000-0000-0000-0000-000000000050', 'Choice between an indwelling pleural catheter and chemical pleurodesis depends on factors including expected prognosis, presence of trapped lung, and patient preference.', 3);
